/* QuadraLab Player — catálogo de drills usado nas sugestões do plano.

   Extraído de EXERCICIOS (autonomo/index.html), o catálogo da Metodologia
   MTY que o treinador já usa — o Player não tem drills próprios, para a IA
   nunca inventar um exercício. Ficam só os de adulto (A) e competição (C),
   sem as famílias de condicionamento físico (CF), coordenação infantil (CO),
   brincadeiras (BR) e posicionamento de duplas (DP).

   Campos: c código · n nome · f família · e estágios · o objetivo ·
   m montagem · g carga · r regressão · p progressão · x corrigir · i ignorar.
   Se o catálogo do treinador mudar, regenerar este arquivo a partir dele. */
const FAMILIAS = {
  IP: "Início do ponto", RT: "Redução de tempo", AT: "Ataque e finalização", JA: "Jogo aplicado com regra",
  FB: "Fundamentos básicos", MV: "Movimentação", DT: "Drills táticos", PDB: "Power drills · base",
  PDR: "Power drills · rede", PDS: "Power drills · saque", DC: "Drills de consistência", DM: "Drills mentais",
  ADV: "Drills avançados MTY", PT: "Padrões táticos", TR: "Trilhos de ensino",
};
const DRILLS = [{"c":"ADV001","n":"Construção em 4 Bolas MTY","f":"ADV","e":["A","C"],"o":"Padrão de 4 bolas com intenção definida para cada uma.","m":"4 bolas: 1a abertura neutra profunda ao centro, 2a construção cruzada com ângulo, 3a preparação deep diagonal, 4a finalização no espaço aberto. Decisão em tempo real nas bolas 3 e 4.","g":"4 séries de 4 bolas","r":"Duas primeiras bolas alimentadas pelo treinador.","p":"Quatro bolas com decisão em tempo real a partir da segunda.","x":"A intenção distinta de cada uma das quatro bolas.","i":"O resultado da quarta bola. Só aplicar após o domínio dos padrões individuais — falha em série desmotiva sem ensinar."},{"c":"ADV002","n":"Ponto com Restrição de Direção","f":"ADV","e":["A","C"],"o":"Inteligência tática sob restrição.","m":"Jogadores jogam pontos reais com restrição definida pelo treinador. Violação = ponto perdido automaticamente.","g":"Sets de 4 games com restrição diferente","r":"Uma restrição por set, anunciada previamente.","p":"Restrição diferente a cada game, anunciada no início do game.","x":"A capacidade de construir dentro do espaço disponível.","i":"A restrição como modelo tático. É ferramenta de treino, não recomendação de jogo."},{"c":"ADV003","n":"Rally com Câmera - Análise MTY","f":"ADV","e":["A","C"],"o":"Vídeo como ferramenta de aprendizado acelerado.","m":"Gravar atleta durante drills. Revisar junto após o treino. Comparar o que o atleta sente com o que acontece. Definir 1 correção prioritária.","g":"15-20 min pós-treino","r":"Gravar e analisar um único padrão.","p":"Análise comparativa entre a autopercepção do jogador e a imagem.","x":"A distância entre o que o jogador acha que faz e o que faz.","i":"Detalhes fora do foco escolhido. Vídeo mostra tudo — o treinador escolhe um."},{"c":"ADV004","n":"Jogo 1x1 com Espectadores","f":"ADV","e":["A","C"],"o":"Execução sob pressão de audiência real.","m":"Atleta joga contra parceiro enquanto outros atletas assistem. Treinador pode comentar em voz alta durante o jogo.","g":"1 set","r":"Poucos espectadores conhecidos.","p":"Público real com placar anunciado em voz alta.","x":"A manutenção da rotina entre pontos com audiência.","i":"O resultado. A exposição é o estímulo."},{"c":"ADV005","n":"Ponto Duplo - 2 Bolas Simultâneas","f":"ADV","e":["A","C"],"o":"Tempo de reação e tomada de decisão ultra-rápida.","m":"Treinador alimenta 2 bolas quase simultaneamente para lados opostos. Atleta escolhe e executa a mais estratégica.","g":"4 séries de 6 situações","r":"Duas bolas com intervalo entre elas.","p":"Duas bolas simultâneas em velocidade real.","x":"A priorização — qual bola atender primeiro.","i":"A qualidade técnica dos dois golpes. O objeto é a decisão sob tempo mínimo."},{"c":"ADV006","n":"Mini-Tênis Tático - Metade da Quadra","f":"ADV","e":["A","C"],"o":"Tato e controle em espaço reduzido com alta densidade de decisão.","m":"Jogo normal mas em metade da quadra (linha de serviço como linha de fundo). Alta densidade de tomadas de decisão.","g":"10-15 min","r":"Espaço ainda menor com bola mais lenta.","p":"Meia quadra completa com pontuação e alvos.","x":"O toque e a leitura em espaço reduzido.","i":"A potência. Ela não existe neste espaço."},{"c":"ADV007","n":"Treino de Padrão Personalizado MTY","f":"ADV","e":["A","C"],"o":"Padrão de jogo ideal específico para o atleta.","m":"Com base no diagnóstico MTY: definir 2-3 padrões de construção e finalização específicos. Repetir em série de 10 até automatizar.","g":"10 repetições por padrão, 3 padrões","r":"Um padrão em vez de três, com bolas alimentadas.","p":"Três padrões alternados em ponto real.","x":"A fidelidade ao padrão que corresponde ao horizonte do jogador.","i":"Padrões que funcionam mas não pertencem ao jogo dele. O compasso é para onde ele vai, não onde está."},{"c":"ADV008","n":"Condicionamento mais Técnica - Circuito","f":"ADV","e":["A","C"],"o":"Integrar condicionamento com execução técnica para simular fadiga.","m":"30 seg de corrida intensa, parar e executar 4 golpes técnicos, 30 seg de corrida, repetir. Manter qualidade técnica sob fadiga.","g":"4 circuitos de 3 min","r":"Circuito de dois minutos com estações mais simples.","p":"Quatro circuitos completos com exigência técnica crescente.","x":"A manutenção do padrão técnico sob fadiga acumulada.","i":"A queda técnica no último circuito. Ela é o dado, não o erro."},{"c":"ADV009","n":"Jogo de Tênis Intuitivo - Sem Instrução","f":"ADV","e":["A","C"],"o":"Avaliar o jogo do atleta sem qualquer instrução.","m":"Atleta joga 1 set completamente sem instrução prévia ou interrupção. Treinador apenas observa e anota.","g":"1 set","r":"Meio set de observação.","p":"Set completo sem qualquer palavra do treinador, com registro estruturado.","x":"O que aparece quando ninguém instrui — este é o jogo real do atleta.","i":"Absolutamente tudo, durante o set. Instruir aqui apaga o dado."},{"c":"ADV010","n":"Torneio Interno - Competição Real","f":"ADV","e":["A","C"],"o":"Ambiente competitivo real para desenvolvimento.","m":"Torneio entre atletas da equipe com placar real, árbitro, aquecimento regulamentar e regras oficiais.","g":"Torneio de 3-4 horas","r":"Torneio interno curto, formato reduzido.","p":"Torneio completo com sorteio, tabela e rotina de competição.","x":"O comportamento entre as partidas, não apenas dentro delas.","i":"Os resultados. Resultado é efeito colateral da performance — a rota do plano não muda por vitória ou derrota."},{"c":"ADV011","n":"FH Inside Out mais Subida Imediata","f":"ADV","e":["A","C"],"o":"Inside out agressivo mais subida imediata a rede.","m":"Inside out agressivo seguido de subida imediata a rede. Treinador alimenta a bola de finalização na rede. Alta velocidade.","g":"6 séries de 4 situações","r":"Inside out alimentado, subida anunciada.","p":"Decisão de subir tomada em tempo real conforme a qualidade do inside out.","x":"O reconhecimento do inside out que autoriza a subida.","i":"O erro do inside out quando a decisão de atacar estava correta. Nunca peça mais efeito para ele cair dentro."},{"c":"ADV012","n":"Devolução do 2o Saque - Ataque Máximo","f":"ADV","e":["A","C"],"o":"Devolução do 2º saque com intenção máxima de ataque.","m":"Treinador serve segundo saque (mais lento). Jogador deve atacar agressivamente. Tolerância zero para devolução neutra.","g":"8-12 devoluções","r":"Segundo saque à meia velocidade; alvo amplo.","p":"Segundo saque real com ponto disputado após a devolução.","x":"A entrada para dentro da quadra e o ponto de contato à frente.","i":"A taxa de erro. Devolução de ataque máximo erra — se não erra, não é ataque máximo."},{"c":"ADV013","n":"Sequência Serve mais Volley mais Smash","f":"ADV","e":["A","C"],"o":"Sequência completa de 3 golpes ofensivos consecutivos.","m":"Saque, voleio, smash (ou lob mais smash). Treinador alimenta após o saque simulando devolução mais lob.","g":"6 séries J","r":"Sequência fracionada em dois golpes.","p":"Sequência completa em velocidade real com adversário defendendo.","x":"A continuidade entre os três golpes, sem parada entre eles.","i":"O erro no terceiro golpe. É o de maior carga da sequência."},{"c":"ADV014","n":"Drop Shot mais Sprint a Rede","f":"ADV","e":["A","C"],"o":"Drop shot seguido de sprint imediato a rede.","m":"Drop shot mais sprint máximo a rede. Treinador alimenta resposta do adversário. Jogador cobre a resposta.","g":"6 séries de 3 situações","r":"Drop shot alimentado com o jogador já adiantado.","p":"Drop shot em ponto real com o adversário chegando na bola.","x":"O sprint imediato — quem faz o drop e observa perde o ponto.","i":"A qualidade do drop shot. O objeto aqui é o que vem depois."},{"c":"ADV015","n":"Jogo com 2 Bolas - Situações Especiais","f":"ADV","e":["A","C"],"o":"Agilidade mental com 2 bolas em quadra.","m":"Treinador entra com 2a bola imediatamente após o rally começar. Atleta continua o ponto com as 2 bolas simultaneamente.","g":"4 séries de 5 situações","r":"Segunda bola introduzida com aviso.","p":"Segunda bola introduzida sem aviso, em qualquer momento do ponto.","x":"A capacidade de reorganizar a decisão no meio do ponto.","i":"A execução técnica sob a surpresa. O objeto é a agilidade mental."},{"c":"ADV016","n":"Ponto Único - Pressão Máxima","f":"ADV","e":["A","C"],"o":"1 único ponto com pressão psicológica máxima.","m":"1 ponto jogado como se fosse a final de um torneio. Treinador constrói a narrativa antes.","g":"5-10 pontos únicos por sessão","r":"Ponto único sem consequência combinada.","p":"Ponto único com consequência real acordada antes.","x":"A rotina completa antes do ponto único.","i":"O resultado do ponto. O que se observa é a rotina que o antecedeu."},{"c":"ADV017","n":"Saída de Posição Defensiva Extrema","f":"ADV","e":["A","C"],"o":"Recuperação de posições defensivas extremas para a posição ofensiva.","m":"Treinador lança bolas que forçam corridas extremas. Após o golpe defensivo, próxima bola vai para posição ofensiva.","g":"4 séries de 6 situações","r":"Posição defensiva menos extrema; alimentação mais lenta.","p":"Posição extrema com duas bolas antes da possibilidade de virada.","x":"A escolha entre defesa alta e defesa acelerada conforme o tempo disponível.","i":"A qualidade da bola defensiva. A função da defesa é parar o ataque, não devolver mais uma bola."},{"c":"ADV018","n":"Slice mais Topspin - Alternancia Tática","f":"ADV","e":["A","C"],"o":"Alternancia tática entre slice e topspin como variação de ritmo.","m":"Rally livre onde atleta alterna conscientemente entre slice e topspin. O parceiro tenta identificar qual vai vir.","g":"7-10 min","r":"Alternância anunciada em blocos.","p":"Alternância decidida em tempo real dentro da troca.","x":"A mudança de ritmo como ferramenta — reduzir e aumentar o tempo do adversário.","i":"A preferência do jogador por uma das duas. As duas precisam existir no repertório."},{"c":"ADV019","n":"Ritmo Acelerado - 80% do Tempo Normal","f":"ADV","e":["A","C"],"o":"Drills em 80% do tempo normal para desenvolver automatização.","m":"Pegar qualquer drill básico e executar com 80% do tempo entre bolas. Menos tempo para pensar, reagir com padrões automatizados.","g":"4 séries de qualquer drill básico","r":"Noventa por cento do tempo normal.","p":"Setenta por cento do tempo normal, em drill já dominado.","x":"A automatização — o que sobrevive quando não há tempo para pensar.","i":"Erros que aparecem sob tempo reduzido em drill ainda não dominado. Só se acelera o que já está estabelecido."},{"c":"ADV020","n":"Simulação Completa de Set - Protocolo MTY","f":"ADV","e":["A","C"],"o":"Set completo com todos os protocolos MTY integrados.","m":"Set completo com: rotina de 20 seg entre pontos, intenção prévia em cada saque, debriefing nos changeovers, análise de padrão pelo treinador.","g":"1 set completo","r":"Meio set com dois protocolos ativos.","p":"Set completo com todos os protocolos e registro posterior.","x":"A integração — os protocolos coexistindo sem que um apague o outro.","i":"O resultado do set. É o encerramento de um ciclo de trabalho, não uma avaliação."},{"c":"AT001","n":"Entra e joga","f":"AT","e":["A"],"o":"","m":"Bola curta; entrar na quadra e jogar ao espaço vazio.","g":"4×8","r":"bola mais alta e central","p":"bola mais baixa e angulada","x":"decisão de entrar, apoio na chegada","i":"se a bola entrou"},{"c":"AT002","n":"Ataque plano de meia quadra","f":"AT","e":["A","C"],"o":"","m":"Bola de três quartos; atacar plano e para a frente.","g":"4×8","r":"bola mais alta, alvo amplo","p":"alvo reduzido, bola mais baixa","x":"ponto de contato à frente, apoio, terminação","i":"margem sobre a rede"},{"c":"AT003","n":"Ataque + finalização à frente","f":"AT","e":["A","C"],"o":"","m":"Atacar e finalizar na rede na bola seguinte.","g":"3×8","r":"finalização com bola lançada","p":"passador tentando o passe","x":"split na zona de voleio","i":"qualidade do voleio nas primeiras sessões"},{"c":"AT004","n":"Duas bolas: arma e converte","f":"AT","e":["A","C"],"o":"","m":"Primeira bola com alvo de segurança (2 m das linhas); segunda com alvo de pressão.","g":"4×6","r":"papéis anunciados antes","p":"o aluno decide qual bola é qual","x":"não inverter os papéis","i":"velocidade"},{"c":"AT005","n":"Ataque por variação","f":"AT","e":["A","C"],"o":"","m":"Atacar por curtinha ou mudança de ritmo, sem acelerar.","g":"3×8","r":"variação anunciada","p":"variação escolhida na hora","x":"compreensão de que isto também é ataque","i":"potência"},{"c":"AT006","n":"Ataque por posição","f":"AT","e":["A","C"],"o":"","m":"Ganhar terreno progressivamente até a resposta ficar impossível, sem bater forte.","g":"3 × 6 pontos","r":"parceiro em bola neutra","p":"parceiro defendendo ativamente","x":"avanço com equilíbrio","i":"velocidade da bola"},{"c":"AT007","n":"Curtinha disfarçada","f":"AT","e":["A","C"],"o":"","m":"Preparação idêntica ao drive até o último instante.","g":"3×8","r":"sem exigência de disfarce","p":"parceiro tentando antecipar","x":"identidade da preparação, mãos macias no contato","i":"perfeição do segundo quique"},{"c":"AT008","n":"Approach paralelo + cobertura","f":"AT","e":["A","C"],"o":"","m":"Approach na paralela e split na zona de voleio, cobrindo a rota provável.","g":"3×8","r":"sem passador","p":"passador com liberdade total","x":"linha de cobertura e timing do split","i":"o voleio"},{"c":"AT009","n":"Approach pesado no backhand","f":"AT","e":["C"],"o":"","m":"Bola pesada caindo atrás do adversário, seguida de voleio de decisão.","g":"3×8","r":"alvo amplo","p":"alvo profundo com margem reduzida","x":"profundidade e direção do approach","i":"o resultado"},{"c":"AT010","n":"Contorno de forehand","f":"AT","e":["C"],"o":"","m":"Inside out e inside in a partir de bola central.","g":"3 × 8 de cada","r":"bola central previsível","p":"bola variando com recuperação exigida","x":"recuo diagonal do pé de trás e recuperação","i":"potência"},{"c":"AT011","n":"Os seis sistemas","f":"AT","e":["C"],"o":"","m":"Ciclo pelos seis padrões de duas bolas do método.","g":"6 blocos de 6","r":"três sistemas por sessão","p":"o parceiro joga livre após a segunda bola","x":"papéis de cada bola","i":"o terceiro golpe"},{"c":"AT012","n":"Ataque sob placar adverso","f":"AT","e":["C"],"o":"","m":"Atacar obrigatoriamente em 15-40.","g":"3 × 6 pontos","r":"placar neutro","p":"com consequência real (série decisiva)","x":"a decisão de atacar acontecer","i":"o resultado — sempre"},{"c":"DC008","n":"Saque - 10 de 10 em Cada Posição","f":"DC","e":["A","C"],"o":"Consistência máxima do saque em todas as posições.","m":"10 saques por posição: T no DC, aberto no DC, T no AC, aberto no AC. Registrar percentual. Meta: 70% em todas.","g":"10 saques por posição","r":"Cinco saques por posição; alvo ampliado.","p":"Registro mensal com meta progressiva por posição.","x":"A repetibilidade do lançamento entre as quatro posições.","i":"O percentual isolado de um dia. O valor deste exercício é a série histórica."},{"c":"DC011","n":"FH com Variação de Spin","f":"DC","e":["A","C"],"o":"Consistência alternando FH topspin e FH plano.","m":"Jogadores alternam: 1 FH com topspin (alta trajetória), 1 FH plano (baixa trajetória). Manter rally por 5 min sem erro.","g":"5 min continuos","r":"Blocos separados: primeiro topspin, depois plano.","p":"Alternância comandada dentro da mesma troca.","x":"A mudança de plano do swing entre as duas trajetórias.","i":"Qual das duas o jogador prefere. As duas precisam existir."},{"c":"DC013","n":"FH mais BH em Sequência Controlada","f":"DC","e":["A","C"],"o":"Transição suave entre FH e BH em sequência definida.","m":"2 FH cruzados mais 2 BH cruzados mais 2 trocas livres. Ciclos de 6 bolas repetidos. Meta: 5 ciclos sem erro.","g":"5 ciclos de 6 bolas","r":"Sequência previsível e ritmo reduzido.","p":"Sequência imprevisível com variação de profundidade.","x":"A transição entre um golpe e outro — é aí que a técnica real aparece.","i":"A técnica de cada golpe isolado."},{"c":"DC014","n":"Voleio mais Golpe de Base - Alternado","f":"DC","e":["A","C"],"o":"Consistência alternando entre voleio e golpe de base.","m":"Treinador alimenta alternando: 1 bola para voleio, 1 para golpe de base. 2 min continuos.","g":"2 min continuos","r":"Reduzir para um minuto; distância menor.","p":"Aumentar para três minutos com direção comandada.","x":"O ajuste de distância e de tempo entre as duas alturas de jogo.","i":"A qualidade individual do voleio e do golpe de base."},{"c":"DC016","n":"Drop Shot mais Lob - Alternado","f":"DC","e":["A","C"],"o":"Alternancia entre drop shot e lob como variação tática.","m":"Treinador alimenta bolas. Jogador alterna: 1 drop shot mais 1 lob mais 1 drop shot. Treina alternancia de golpes de controle extremos.","g":"4 séries de 6 bolas","r":"Alternância anunciada, com bola alimentada.","p":"Escolha entre drop e lob decidida pelo jogador conforme a posição do adversário.","x":"O disfarce comum aos dois golpes — a preparação precisa ser a mesma.","i":"A eficácia isolada de cada um. O objeto é a alternância."},{"c":"DC017","n":"Passada mais Lob - Decisão","f":"DC","e":["A","C"],"o":"Decisão entre passada e lob com adversário na rede.","m":"Treinador na rede. Quando avança: lob indicado. Quando recua: passada indicada.","g":"6 séries de 6 situações","r":"Decisão anunciada pelo treinador antes de cada bola.","p":"Decisão livre com adversário real na rede.","x":"O tempo da decisão — antes da preparação, com base na posição do adversário.","i":"A opção escolhida quando a leitura estava certa. Passada e lob são respostas igualmente válidas."},{"c":"DC018","n":"FH 4 Direções - Precisão","f":"DC","e":["A","C"],"o":"Precisão do FH nos 4 cantos da quadra.","m":"Treinador sinaliza um dos 4 cantos antes de alimentar. Jogador executa FH para o canto indicado.","g":"6 séries de 4 bolas","r":"Duas direções em vez de quatro; alvos amplos.","p":"Quatro direções com alvos estreitos e comando em tempo real.","x":"A repetibilidade do ponto de contato nas quatro direções.","i":"A velocidade. Precisão e velocidade não se treinam na mesma série."},{"c":"DC019","n":"BH 4 Direções - Precisão","f":"DC","e":["A","C"],"o":"Precisão do BH nos 4 cantos da quadra.","m":"Mesma estrutura do DC018 com BH. Sinalização dos 4 cantos pelo treinador.","g":"6 séries de 4 bolas","r":"Duas direções com alvos amplos.","p":"Quatro direções sob comando, com contagem de acertos consecutivos.","x":"A consistência do apoio nas direções menos treinadas.","i":"A comparação com o forehand. São golpes de margens diferentes."},{"c":"DM001","n":"Rotina de 20 Segundos MTY","f":"DM","e":["A","C"],"o":"Rotina pre-ponto MTY: respirar, resetar, decidir.","m":"Em exercícios de pontos: após cada ponto, 20 seg para respirar, olhar para as cordas e decidir a tática do próximo ponto.","g":"Integrado a qualquer exercício de pontos","r":"Rotina reduzida a duas etapas: respirar e decidir.","p":"Rotina completa mantida em situação de placar e sob fadiga.","x":"A presença das três etapas — respirar, fechar o ponto anterior, decidir o próximo.","i":"O resultado do ponto seguinte. O objetivo é executar a decisão tomada nos vinte segundos, não vencer o ponto."},{"c":"DM002","n":"Diagnóstico de Estilo de Jogo","f":"DM","e":["A","C"],"o":"Mapear o padrão natural de jogo para construir o plano MTY individual.","m":"Atleta joga 1 set enquanto treinador anota: golpe favorito de abertura, direção preferida sob pressão, onde erra a maioria dos pontos, comportamento nos pontos decisivos.","g":"1 set de observação mais 20 min debriefing","r":"Observação restrita a um único bloco de jogo.","p":"Observação em set completo com registro estruturado por padrão.","x":"A leitura do padrão natural do jogador, sem intervenção durante a observação.","i":"Tudo, durante a observação. Corrigir aqui destrói o dado que se quer coletar."},{"c":"DM003","n":"Pontos com Intenção Prévia","f":"DM","e":["A","C"],"o":"Execução de plano tático definido antes de cada ponto.","m":"Antes de cada ponto, jogador anuncia o plano em voz alta. Treinador avalia se o plano foi seguido, independente do resultado.","g":"10-15 pontos","r":"Intenção anunciada em voz alta antes de cada ponto.","p":"Intenção silenciosa, com verificação no debriefing.","x":"A correspondência entre a intenção declarada e o que foi jogado.","i":"O resultado do ponto. A medida é a fidelidade ao plano, não a vitória."},{"c":"DM004","n":"Foco de Processo - Não Resultado","f":"DM","e":["A","C"],"o":"Foco no processo de execução, não no resultado.","m":"Rally livre com instrução: a cada ponto, o atleta identifica UM aspecto que executou bem, independente de ter ganho ou perdido.","g":"5-7 min","r":"Um único indicador de processo por série.","p":"Três indicadores simultâneos, com registro após cada bloco.","x":"A capacidade de nomear o que foi executado, independentemente do resultado.","i":"O placar. Ele está deliberadamente fora deste exercício."},{"c":"DM005","n":"Pontos sob Pressão Artificial","f":"DM","e":["A","C"],"o":"Exposição a pressão artificial para desenvolver regulação emocional.","m":"Jogadores jogam pontos mas cada game perdido deve ser anunciado em voz alta com o placar atual. Treinador pode adicionar comentários.","g":"1 set completo","r":"Pressão moderada: placar levemente desfavorável.","p":"Pressão máxima com consequência real combinada previamente.","x":"A manutenção da rotina entre pontos sob pressão.","i":"O resultado. E também as reações — elas são o dado que se está coletando."},{"c":"DM006","n":"Breathing Between Points","f":"DM","e":["A","C"],"o":"Hábito de respiração consciente entre os pontos.","m":"Em qualquer exercício de pontos: após cada ponto (ganho ou perdido), o jogador faz 3 respirações diafragmáticas antes de continuar.","g":"Integrado a qualquer exercício","r":"Respiração guiada em voz alta pelo treinador.","p":"Respiração autônoma verificada por observação externa.","x":"A presença da respiração completa antes do saque ou da devolução.","i":"O ritmo de jogo. Respirar leva o tempo que leva."},{"c":"DM007","n":"Rally com Distrator","f":"DM","e":["A","C"],"o":"Capacidade de focar sob distrações controladas.","m":"Treinador tenta distrair o atleta durante o rally: faz barulho, comenta erros, faz gestos. Atleta mantém foco sem responder.","g":"5-7 min","r":"Distrator único e previsível.","p":"Múltiplos distratores imprevisíveis, incluindo ruído e movimento.","x":"O retorno da atenção após a distração — não a ausência de distração.","i":"As distrações que ocorrem. Elas são o exercício, não a interferência nele."},{"c":"DM008","n":"Jogo Silencioso - Sem Reações","f":"DM","e":["A","C"],"o":"Neutralidade emocional eliminando reações verbais e corporais.","m":"Jogadores jogam pontos sem qualquer reação verbal ou gestual - nem positiva nem negativa.","g":"1 set completo","r":"Silêncio apenas verbal; gestos permitidos.","p":"Neutralidade completa, verbal e corporal, no set inteiro.","x":"A neutralidade como ferramenta de economia, não como repressão.","i":"A comparação com o comportamento habitual do jogador. Este é um exercício, não um padrão a impor."},{"c":"DM009","n":"Decisão em Milissegundos - Bola Colorida","f":"DM","e":["A","C"],"o":"Velocidade de decisão com estímulo visual de cores.","m":"Treinador usa bolas de 2 cores. Cor vermelha: cruzada. Cor amarela: paralela. Jogador reage a cor assim que vê a bola.","g":"4 séries de 8 bolas","r":"Duas cores em vez de mais; anúncio antecipado.","p":"Anúncio no instante do quique, com três estímulos possíveis.","x":"A velocidade entre o estímulo e o início da preparação.","i":"A qualidade técnica do golpe. Aqui só o tempo de decisão está em jogo."},{"c":"DM010","n":"Análise de Vídeo - Pós-Treino","f":"DM","e":["A","C"],"o":"Vídeo como ferramenta de autoconhecimento e aprendizado acelerado.","m":"Gravar o atleta durante drills principais. Revisar junto após o treino. Atleta identifica diferença entre o que sente e o que acontece.","g":"15-20 min pós-treino","r":"Analisar um único aspecto, escolhido antes da gravação.","p":"Análise comparativa entre duas sessões distantes no tempo.","x":"O que o jogador vê antes de o treinador falar.","i":"Detalhes que o jogador ainda não é capaz de perceber. Vídeo mostra demais — escolha um ponto."},{"c":"DM011","n":"Jogo com Placar Imaginário","f":"DM","e":["A","C"],"o":"Pressão de jogo real com placar imaginário específico.","m":"Treinador anuncia situação: 5-5 no terceiro set, break point. Jogador joga o ponto como se fosse real.","g":"10-15 pontos","r":"Placar imaginário anunciado uma vez, sem variação.","p":"Placar variando a cada ponto, incluindo situações de desvantagem extrema.","x":"A mudança de comportamento entre os placares.","i":"O resultado do bloco. O objeto é a variação de conduta conforme o placar."},{"c":"DM012","n":"Sequência de Erros - Recuperação Mental","f":"DM","e":["A","C"],"o":"Capacidade de recuperação após erros consecutivos.","m":"Treinador alimenta 3 bolas difíceis que forçam erro. Na 4a bola, uma bola fácil. Atleta deve executar a 4a bola perfeitamente.","g":"6 séries","r":"Sequência de dois erros induzidos em vez de mais.","p":"Sequência longa de erros com pressão adicional de tempo.","x":"O tempo que o jogador leva para retomar a rotina após a sequência.","i":"Os erros em si. Eles são induzidos de propósito."},{"c":"DM013","n":"Pontos sem Pontuação - Só Execução","f":"DM","e":["A","C"],"o":"Remover a pressão do placar para focar na execução técnica.","m":"Jogadores jogam pontos normais mas sem placar. Ninguém conta. Foco exclusivo na execução com intenção.","g":"10-15 min","r":"Blocos de cinco minutos.","p":"Sessão inteira sem pontuação, com registro apenas de execução.","x":"O foco na execução quando o placar não existe.","i":"Qualquer menção a resultado. É exatamente o que se está removendo."},{"c":"DM014","n":"Visualização Pre-Treino - 5 Minutos","f":"DM","e":["A","C"],"o":"Visualização como preparação mental para o treino.","m":"Antes de entrar em quadra: 5 min de visualização. Atleta fecha os olhos e visualiza executando perfeitamente os drills da sessão.","g":"5 min pre-treino","r":"Visualização de um único golpe por três minutos.","p":"Visualização de um ponto completo com adversário específico.","x":"A nitidez sensorial da imagem, não a duração.","i":"A dificuldade de visualizar no início. É uma habilidade que se treina."},{"c":"DM015","n":"Foco em 1 Objetivo por Sessão","f":"DM","e":["A","C"],"o":"Hábito de definir e manter 1 objetivo técnico ou tático por sessão.","m":"Antes de cada sessão, treinador e atleta definem 1 objetivo. Todos os drills são avaliados por esse único critério.","g":"Sessão inteira","r":"Objetivo definido pelo treinador.","p":"Objetivo definido pelo jogador e revisado por ele no fim da sessão.","x":"A manutenção do objetivo do início ao fim da sessão.","i":"Outras lacunas que aparecem durante a sessão. Elas entram na próxima — não nesta."},{"c":"DM016","n":"Jogo com Adversário Desconhecido","f":"DM","e":["A","C"],"o":"Adaptação tática a estilos diferentes.","m":"Atleta joga contra adversário de estilo diferente do usual: destros e canhotos, defensivos e agressivos, rápidos e lentos.","g":"1 set","r":"Adversário conhecido com estilo alterado por restrição.","p":"Adversário real desconhecido, sem informação prévia.","x":"O tempo que o jogador leva para identificar o padrão do adversário.","i":"O resultado. A leitura é a medida."},{"c":"DM017","n":"Checklist Mental Pre-Saque","f":"DM","e":["A","C"],"o":"Checklist mental consistente antes de cada saque.","m":"Antes de cada saque: 1. Posição dos pés. 2. Olhar o alvo. 3. Respiração. 4. Visualizar a trajetória. 5. Executar.","g":"Integrado a todos os drills de saque","r":"Checklist de dois itens.","p":"Checklist completo mantido sob pressão de placar.","x":"A constância do checklist entre o primeiro e o segundo saque.","i":"O conteúdo do checklist. Ele é do jogador, não do treinador."},{"c":"DM018","n":"Pontos com Mudança de Tática","f":"DM","e":["A","C"],"o":"Capacidade de mudar de plano tático durante o jogo.","m":"2 games com tática A, depois 2 games com tática B. Avaliar qual funcionou melhor.","g":"4 games totais","r":"Mudança de tática anunciada pelo treinador entre os games.","p":"Mudança decidida pelo jogador com base na leitura do adversário.","x":"A capacidade de abandonar um plano que não está funcionando.","i":"O plano abandonado. Mudar não é falha de convicção."},{"c":"DM019","n":"Simulação de Matchday - Rotina Completa","f":"DM","e":["A","C"],"o":"Simular a rotina completa de um dia de competição.","m":"Atleta chega como se fosse competição: aquecimento físico, visualização, rotina de pre-jogo, entrada com postura de competição.","g":"Sessão completa de 2h","r":"Simular apenas a rotina de aquecimento e o primeiro set.","p":"Simulação completa incluindo deslocamento, alimentação e intervalos reais.","x":"A fidelidade da rotina ao que acontecerá no dia da competição.","i":"O desempenho técnico. A rotina é o objeto."},{"c":"DM020","n":"Debriefing Pós-Jogo Estruturado","f":"DM","e":["A","C"],"o":"Análise pós-competição para acelerar o aprendizado.","m":"Após jogo ou simulação: 15 min de análise estruturada. O que funcionou. O que não funcionou. Por que os erros. O que trabalhar.","g":"15 min pós-jogo","r":"Três perguntas fixas de debriefing.","p":"Debriefing completo com registro escrito e comparação com jogos anteriores.","x":"A separação entre o que foi decisão e o que foi execução.","i":"O resultado do jogo. Ele já aconteceu e não é o assunto do debriefing."},{"c":"DT001","n":"Armar Dir - Finalizar Esq 1","f":"DT","e":["A","C"],"o":"Construção pelo FH cruzado e finalização pelo invertido.","m":"FH cruzado profundo (construção) e FH invertido (finalização). Alvo definido. O cruzado deve ser fundo, não atacar na bola de construção.","g":"4 séries de 6-8 bolas","r":"Treinador alimenta as bolas de construção; o jogador executa só a finalização.","p":"Construção livre em número variável de bolas, com a finalização decidida em tempo real.","x":"O reconhecimento da bola que autoriza a virada para o invertido.","i":"O erro da bola de finalização. Se a decisão de finalizar estava certa, a decisão fica; corrige-se apoio ou contato — nunca se pede mais efeito."},{"c":"DT002","n":"Armar Dir - Finalizar Esq 2","f":"DT","e":["A","C"],"o":"Construção em 3 tempos: FH profundo, angulado e paralelo.","m":"3 bolas: FH cruzado profundo, FH angulado curto abrindo quadra, FH paralelo finalização. Alvo para cada bola.","g":"4 séries de 6-9 bolas","r":"Reduzir a dois tempos: profundo e paralelo, sem o angulado.","p":"Ordem dos três tempos definida pelo jogador em tempo real.","x":"A sequência de intenções — cada bola tem função distinta e o corpo precisa mudar com ela.","i":"A velocidade das bolas de construção. Construção não é ataque."},{"c":"DT003","n":"Armar Esq - Finalizar Dir 1","f":"DT","e":["A","C"],"o":"Padrão inverso: BH cruzado e finalização pelo FH.","m":"BH cruzado profundo (construção) mais FH cruzado (finalização). Padrão favorito de jogadores com BH sólido.","g":"4 séries de 6-8 bolas","r":"Alimentação das bolas de backhand pelo treinador.","p":"Padrão iniciado a partir do saque.","x":"A qualidade do backhand cruzado que sustenta o padrão até a virada.","i":"A ansiedade de virar cedo nas primeiras séries. Vira-se cedo demais quando a paciência ainda não existe — isso se constrói, não se corrige com instrução."},{"c":"DT004","n":"Armar Esq - Finalizar Dir 2","f":"DT","e":["A","C"],"o":"Construção pelo BH com opções de finalização em 3 variantes.","m":"BH cruzado profundo, FH invertido, FH inside in. Versão avançada: treinador sinaliza direção da 3a bola em tempo real.","g":"4 séries de 6-9 bolas","r":"Uma variante por série, anunciada previamente.","p":"As três variantes disponíveis, escolha em tempo real.","x":"A leitura da posição do adversário antes de escolher a variante.","i":"Qual variante foi escolhida. Se a leitura estava certa, todas as três são corretas."},{"c":"DT005","n":"Saque e 1a Bola DC","f":"DT","e":["A","C"],"o":"Abertura do ponto no DC com intenção tática.","m":"Jogador saca e golpeia a 1ª bola. Posição do saque varia. Direção da 1ª bola decide ANTES do saque.","g":"1 série de 16 combinações por lado","r":"Reduzir para oito combinações; decisão anunciada em voz alta antes do saque.","p":"Combinação decidida e não anunciada, com o ponto disputado até o fim.","x":"A decisão tomada antes do saque e mantida na primeira bola.","i":"O percentual de primeiro saque nas primeiras semanas. O objeto aqui é o encadeamento, não o saque."},{"c":"DT006","n":"Saque e 1a Bola AC","f":"DT","e":["A","C"],"o":"Abertura do ponto no AC.","m":"Mesma estrutura do DT005 no AC. Saque aberto no AC vai para o BH do adversário.","g":"1 série de 16 combinações por lado","r":"Oito combinações com anúncio prévio da direção.","p":"Ponto disputado após a primeira bola, com registro do resultado do padrão.","x":"A adaptação do padrão ao ângulo diferente do lado da vantagem.","i":"A transposição direta do padrão do lado da igualdade. Os dois lados têm geometrias distintas."},{"c":"DT007","n":"Devolução e 1a Bola","f":"DT","e":["A","C"],"o":"Abertura do ponto na devolução com intenção de direção.","m":"Treinador saca variando posição. Após a devolução, lança bola no lado oposto para golpe cruzado.","g":"1 série de 16 combinações por lado","r":"Saque à meia velocidade e direção anunciada.","p":"Saque real com direção variada e ponto disputado.","x":"A intenção de direção decidida antes da devolução.","i":"A profundidade da devolução quando a decisão está certa e o saque foi bom."},{"c":"DT008","n":"Comando FH - 3 Direções","f":"DT","e":["A","C"],"o":"Pressionar com FH em 3 direções consecutivas.","m":"2 bolas na direita (cruzada e paralela de FH) mais 1 bola no lado esquerdo (inside out). Pressão continua.","g":"4 séries de 6-9 bolas","r":"Duas direções em vez de três.","p":"Três direções com o adversário disputando o ponto livremente após a terceira.","x":"A manutenção da posição de comando entre as três bolas.","i":"Erros na terceira bola. Três bolas de pressão consecutivas é carga alta — o erro final é esperado."},{"c":"DT009","n":"FH Inside Out e Inside In - Decisão","f":"DT","e":["A","C"],"o":"Decisão entre inside out e inside in sob pressão.","m":"Treinador lança bolas para o lado do BH. Jogador decide entre FH inside out (cruzado) ou inside in (paralelo).","g":"4 séries de 8 bolas","r":"Direção anunciada pelo treinador antes de cada bola.","p":"Decisão livre com o adversário se reposicionando de verdade.","x":"O tempo da decisão — ela precisa acontecer antes da preparação, não durante.","i":"Qual das duas foi escolhida. Ambas são corretas; o que se observa é se a escolha foi feita a tempo."},{"c":"DT010","n":"Ponto Restrição - Só Cruzadas","f":"DT","e":["A","C"],"o":"Controle tático sob restrição de direção.","m":"Jogadores jogam pontos normais mas SOMENTE com golpes cruzados. Ponto perdido automaticamente se bater na paralela.","g":"Sets de 4 games","r":"Restringir apenas um dos jogadores.","p":"Restrição para os dois, com games completos e placar valendo.","x":"A construção do ponto dentro do espaço restrito.","i":"A monotonia da troca. O ponto do exercício é justamente a paciência que ele impõe."},{"c":"DT011","n":"Ponto Restrição - FH Dominante","f":"DT","e":["A","C"],"o":"Jogo construído exclusivamente pelo FH.","m":"Atleta deve usar o FH sempre que possível, correndo para usar o FH mesmo em bolas de BH.","g":"Sets de 4 games","r":"Permitir backhand em bolas de emergência.","p":"Restrição total, com o adversário atacando o lado do backhand deliberadamente.","x":"O deslocamento que viabiliza o forehand invertido.","i":"A leitura de que isto é um modelo de jogo. É um exercício de restrição, não uma recomendação tática."},{"c":"DT012","n":"Ponto Restrição - BH Dominante","f":"DT","e":["A","C"],"o":"Jogo construído pelo BH.","m":"Atleta deve usar o BH sempre que possível. Restrição mais difícil para a maioria dos destros.","g":"Sets de 4 games","r":"Permitir forehand nas bolas curtas.","p":"Restrição total com pressão deliberada no lado do forehand.","x":"A capacidade de construir e não apenas sustentar com o backhand.","i":"O número de erros. O lado menos usado erra mais — é o motivo do exercício existir."},{"c":"DT013","n":"Rally com Zona Proibida - Centro","f":"DT","e":["A","C"],"o":"Evitar o centro da quadra ao golpear.","m":"Em rally livre, o centro da quadra do adversário é zona proibida. Só golpes para os cantos contam como positivos.","g":"5-7 min","r":"Zona proibida estreita, apenas o corredor central.","p":"Zona ampliada, com perda do ponto ao acertá-la.","x":"A consciência de direção em cada golpe.","i":"A velocidade. Bola lenta e fora do centro cumpre o objetivo."},{"c":"DT014","n":"Rally com Zona Proibida - Curta","f":"DT","e":["A","C"],"o":"Evitar bolas curtas em todos os golpes.","m":"Em rally, bola antes da linha de serviço do adversário é ponto negativo. Força profundidade em todos os golpes.","g":"5-7 min","r":"Marcar a zona curta com cones visíveis e não penalizar de imediato.","p":"Perda do ponto na primeira bola curta, sem aviso.","x":"A altura sobre a rede — profundidade nasce da altura.","i":"A velocidade da bola. Bola alta e profunda é bola correta aqui."},{"c":"DT015","n":"3 Bolas de Construção mais Winner","f":"DT","e":["A","C"],"o":"Padrão de 3 bolas de construção seguidas de finalização.","m":"Treinador alimenta 3 bolas de rally neutro. Na 4a bola, jogador tenta o winner. Regra: não pode tentar antes da 4a bola.","g":"6 séries de 4 bolas","r":"Treinador alimenta as três bolas de construção.","p":"Número de bolas de construção variável, com o jogador decidindo quando finalizar.","x":"O reconhecimento do momento em que a construção autoriza a finalização.","i":"O resultado do winner. Decisão certa com erro de execução é corrigida na execução, nunca na decisão."},{"c":"DT016","n":"Abertura de Quadra mais Subida a Rede","f":"DT","e":["A","C"],"o":"Abrir quadra pelo cruzado e subir pela paralela.","m":"FH cruzado com ângulo para abrir espaço, depois bola curta para approach pela paralela e subida à rede.","g":"6 séries de 3 bolas J","r":"Bola de subida alimentada pelo treinador.","p":"Ponto disputado até o fim com o adversário buscando a passada.","x":"A continuidade do deslocamento entre a abertura e a subida.","i":"A qualidade do voleio final nas primeiras séries. O objeto é o encadeamento."},{"c":"DT017","n":"Devolução Chip-and-Charge","f":"DT","e":["A","C"],"o":"Devolução agressiva com subida imediata a rede.","m":"Treinador saca. Jogador executa chip (BH slice baixa sobre a rede) e avança imediatamente a rede. Finaliza com voleio.","g":"6 séries de 4 situações J","r":"Saque à meia velocidade e subida anunciada.","p":"Saque real, subida decidida em tempo real conforme a devolução possível.","x":"O primeiro passo para dentro no instante da devolução.","i":"A profundidade da devolução. Chip-and-charge vive da chegada, não da bola."},{"c":"DT018","n":"Jogo 1x1 com Placar Invertido","f":"DT","e":["A","C"],"o":"Resiliência e estratégia sob pressão de desvantagem.","m":"Jogadores jogam sets mas o placar começa em 0-4 para o atleta treinando. Ele precisa ganhar todos os games restantes.","g":"1 set por treino","r":"Desvantagem menor no placar inicial.","p":"Desvantagem maior, com o set valendo dentro de um bloco de competição.","x":"A rotina entre pontos sob desvantagem.","i":"O resultado do set. O placar aqui é ferramenta, não medida — o resultado é efeito colateral da performance."},{"c":"DT019","n":"Pontos de Tiebreak - Situações Decisivas","f":"DT","e":["A","C"],"o":"Execução nos pontos mais importantes do tiebreak.","m":"Jogadores jogam somente situações de tiebreak: 6-6, 7-6, etc. Treinador pode sinalizar a situação antes do ponto.","g":"10-15 pontos","r":"Pontos isolados sem contexto de placar.","p":"Tiebreak completo com registro dos pontos decisivos.","x":"A decisão tática nos pontos de maior peso e a manutenção da rotina.","i":"O resultado. O que se observa é se a decisão do ponto grande foi a mesma do ponto pequeno."},{"c":"DT020","n":"Construção BH Profundo mais Inside In","f":"DT","e":["A","C"],"o":"BH fundo abre, inside in finaliza.","m":"BH cruzado profundo. Treinador lança 2a bola para FH executar inside in.","g":"4 séries de 6 bolas","r":"Alimentação da bola profunda de backhand pelo treinador.","p":"Padrão iniciado no saque, com adversário real defendendo.","x":"A profundidade do backhand que cria o espaço para o inside in.","i":"A velocidade do backhand de abertura. Ele abre com profundidade, não com força."},{"c":"DT021","n":"Defesa Profunda mais Transição Ataque","f":"DT","e":["A","C"],"o":"Saída da posição defensiva para o ataque em sequência de 3 bolas.","m":"2 bolas profundas (defesa) mais 1 bola mais curta ou lenta (oportunidade). Atleta deve reconhecer e mudar para modo ataque.","g":"4 séries de 6 bolas","r":"Duas bolas em vez de três, com a virada anunciada.","p":"Número de bolas defensivas variável e virada decidida pelo jogador.","x":"O reconhecimento da bola que autoriza a transição.","i":"A escolha entre defesa alta e acelerada. As duas são válidas — a função da defesa é parar o ataque."},{"c":"DT022","n":"Jogo 1x1 - Só Pontos Longos","f":"DT","e":["A","C"],"o":"Consistência e estratégia em pontos de alta duração.","m":"Pontos só contam se tiverem pelo menos 6 golpes. Pontos que terminam antes são refeitos.","g":"10-15 pontos válidos","r":"Duração mínima menor por ponto.","p":"Duração mínima maior, com pontos abaixo do mínimo anulados.","x":"A capacidade de sustentar qualidade técnica ao longo do ponto.","i":"A estratégia de encurtar o ponto. Neste exercício ela está temporariamente suspensa — não é correção de método."},{"c":"DT023","n":"Serve-Volley Clássico","f":"DT","e":["A","C"],"o":"Padrão serve-volley como tática de surpresa.","m":"Jogador saca e avança imediatamente a rede. Split step antes do voleio. Finalizar com 1-2 voleios.","g":"6 séries de 6 pontos J","r":"Subida a partir de saque alimentado, sem pressão de devolução.","p":"Serve-volley em ponto real com devolução de ataque.","x":"O split step antes do primeiro voleio e a distância percorrida após o saque.","i":"O percentual de pontos ganhos. Serve-volley é ferramenta de variação — o volume de acerto não é a medida."},{"c":"DT024","n":"Segunda Bola do Adversário - Ataque","f":"DT","e":["A","C"],"o":"Aproveitar a segunda bola do adversário para atacar.","m":"Treinador simula segundo saque fraco (bola mais lenta e curta). Jogador deve reconhecer e atacar agressivamente.","g":"8-12 devoluções","r":"Segundo saque alimentado à meia velocidade.","p":"Segundo saque real com o ponto disputado após a devolução.","x":"A entrada para dentro da quadra na devolução do segundo saque.","i":"O erro da devolução agressiva. Devolução de ataque que nunca erra não é ataque."},{"c":"DT025","n":"Lob Tático mais Posicionamento na Rede","f":"DT","e":["A","C"],"o":"Quando usar o lob e como se reposicionar após.","m":"Treinador na rede. Quando recua: lob indicado. Quando mantém posição: passada indicada. Decisão baseada na posição.","g":"6 séries de 6 situações","r":"Lob alimentado sem adversário na rede.","p":"Adversário real na rede buscando o smash, com ponto disputado.","x":"O reposicionamento imediato após o lob — a decisão continua depois da bola sair.","i":"A profundidade do lob nas primeiras séries."},{"c":"DT026","n":"Drop Shot mais Subida a Rede","f":"DT","e":["A","C"],"o":"Drop shot seguido de avanço imediato a rede.","m":"Drop shot mais sprint máximo a rede. Treinador alimenta resposta do adversário. Jogador cobre a resposta.","g":"6 séries de 4 situações","r":"Drop shot alimentado com o jogador já dentro da quadra.","p":"Drop shot em ponto real com o adversário buscando a bola.","x":"A subida imediata — quem faz drop e fica é quem perde o ponto.","i":"A qualidade do drop shot. Aqui o objeto é o que vem depois dele."},{"c":"DT027","n":"Jogo com Pontuação por Zona","f":"DT","e":["A","C"],"o":"Consciência de onde golpear em cada situação.","m":"Dividir quadra em 3 zonas: vermelha (próxima -1), amarela (central 0), verde (fundo +1). Acumular pontos por zona.","g":"10 games","r":"Zonas amplas com pontuação simples.","p":"Zonas estreitas com pesos diferentes por zona.","x":"A consciência de destino antes da preparação.","i":"A pontuação final. As zonas são linguagem, não placar."},{"c":"DT028","n":"Sequência Saque mais 3 Bolas","f":"DT","e":["A","C"],"o":"Padrão completo de abertura no saque com 3 bolas.","m":"Jogador saca, recebe a 1ª bola e joga mais 2 golpes com intenção tática definida. Não pode tentar winner antes da 3a bola.","g":"8-12 séries de 4 bolas","r":"Saque mais duas bolas.","p":"Saque mais três bolas com o ponto disputado a seguir.","x":"A manutenção da iniciativa ao longo das três bolas.","i":"O erro na terceira bola. É o ponto de maior carga da sequência."},{"c":"DT029","n":"Triângulo Tático - 3 Zonas","f":"DT","e":["A","C"],"o":"Tomada de decisão tática em 3 zonas diferentes.","m":"Cones demarcam 3 zonas: defensiva, construção e finalização. Conforme a zona, o atleta executa o golpe tático correspondente.","g":"4 séries de 9 situações","r":"Duas zonas em vez de três, com decisão anunciada.","p":"Três zonas com decisão em tempo real e adversário ativo.","x":"A leitura da zona de onde a bola está sendo jogada — a decisão muda com a posição.","i":"A execução técnica dentro de cada zona. O objeto é a decisão."},{"c":"DT030","n":"Ponto Livre - Aplicação Tática","f":"DT","e":["A","C"],"o":"Integrar todos os padrões táticos em situação de jogo livre.","m":"Jogadores jogam sets normais mas após cada ponto identificam o padrão tático que funcionou ou falhou. Debriefing de 30 seg após cada game.","g":"1 set de 6 games","r":"Um padrão obrigatório por game, anunciado antes.","p":"Jogo totalmente livre com debriefing sobre os padrões que apareceram.","x":"Se os padrões treinados aparecem espontaneamente ou só sob comando.","i":"Tudo, durante o jogo. Este é um exercício de observação — a correção vem no debriefing."},{"c":"FB001","n":"FH Cruzado Profundo","f":"FB","e":["A","C"],"o":"Consistência e profundidade do forehand cruzado.","m":"Jogadores trocam bolas na cruzada de forehand buscando o último metro do fundo. Ritmo moderado. Treinador observa preparação, ponto de contato e finalização.","g":"5-7 min","r":"Treinador alimenta de cesta em vez de troca livre; quadra reduzida ao corredor da cruzada.","p":"Alvo no último metro; contar 8 cruzadas seguidas dentro do alvo antes de encerrar a série.","x":"Ponto de contato à frente do corpo e altura da bola sobre a rede — profundidade vem da altura, não da força.","i":"Velocidade da bola e escolha de direção. Bola curta aqui é erro de altura, não de intenção — não peça mais efeito para corrigir."},{"c":"FB002","n":"BH Cruzado Profundo","f":"FB","e":["A","C"],"o":"Consistência e profundidade do backhand cruzado.","m":"Mesmo formato do FB001 com backhand cruzado. Para dois mãos: verificar braço não-dominante ativo. Para uma mão: checar posição do ombro no contato.","g":"5-7 min","r":"Treinador alimenta; bola parada no ponto alto para quem ainda não tem timing de backhand.","p":"Alvo no último metro e alternância de altura sob comando do treinador.","x":"Duas mãos: braço não-dominante ativo na aceleração. Uma mão: ombro fechado no contato.","i":"Velocidade. Diferença entre uma e duas mãos não se corrige — se acomoda; o gesto que o jogador traz é o ponto de partida."},{"c":"FB003","n":"FH Paralelo","f":"FB","e":["A","C"],"o":"Forehand paralelo com profundidade e controle.","m":"Jogadores trocam bolas na paralela de forehand. Bola funda e plana, sem ângulo. Verificar fechamento do ombro antes do contato.","g":"5-7 min","r":"Bola alimentada de posição fixa, sem deslocamento lateral.","p":"Mudança de direção sob comando: duas paralelas, uma cruzada, retomar.","x":"Fechamento do ombro antes do contato e transferência de peso para frente.","i":"O erro para fora. Ele é consequência de ombro aberto cedo, não de excesso de força — corrija o ombro e o erro sai sozinho."},{"c":"FB004","n":"BH Paralelo","f":"FB","e":["A","C"],"o":"Backhand paralelo com profundidade.","m":"Jogadores trocam bolas na paralela de backhand. Para dois mãos: quadris devem rodar completamente na direção da paralela. Para uma mão: extensão do braço mais longa que no cruzado.","g":"5-7 min","r":"Alimentação de cesta com bola alta e lenta; encurtar a distância do alvo.","p":"Alternar paralela e cruzada mantendo profundidade em ambas.","x":"Duas mãos: rotação completa do quadril na direção da paralela. Uma mão: extensão longa do braço.","i":"A taxa de acerto. Este é o golpe de menor consistência natural — use o número como diagnóstico, não como meta da sessão."},{"c":"FB005","n":"Rally do Meio - FH e BH","f":"FB","e":["A","C"],"o":"Aquecer e desenvolver leitura de bola usando ambos os golpes.","m":"Jogadores trocam bolas pelo centro usando FH e BH conforme a bola chega. Sem restrição de direção. Foco em profundidade e recuperação ao centro entre golpes.","g":"7-10 min","r":"Reduzir o espaço de deslocamento; treinador anuncia o lado antes de alimentar.","p":"Sem anúncio, com variação de altura e profundidade.","x":"Leitura antecipada do lado e a transição entre um golpe e o outro.","i":"A técnica de cada golpe isolado. Aqui se observa a passagem de um para o outro — é nela que a técnica real aparece."},{"c":"FB007","n":"BH com Alvo - Cruzada","f":"FB","e":["A","C"],"o":"Precisão do BH cruzado com alvo visual.","m":"Área no canto cruzado (min 1mx1m). Jogadores trocam BH cruzado buscando a área. Sistema de contagem: meta de 16 acertos. Use como avaliação mensal.","g":"16 acertos","r":"Ampliar a área do alvo; alimentação de cesta.","p":"Reduzir o alvo; contar acertos consecutivos e reiniciar a contagem ao errar.","x":"Direção e ponto de contato. O alvo é referência visual, não obrigação.","i":"Velocidade da bola. Perseguir alvo com força é o caminho mais curto para descaracterizar o golpe."},{"c":"FB008","n":"FH Alto e Baixo","f":"FB","e":["A","C"],"o":"Variação de trajetória do FH - plana e com topspin.","m":"Jogadores alternam FH alto (topspin, parabólico) e FH baixo (plano, rápido) na cruzada. A cada dois golpes mudar a trajetória. Treina controle de spin e variação de ritmo.","g":"4 séries de 8 bolas","r":"Trabalhar apenas uma das trajetórias por série.","p":"Alternância sob comando do treinador, sem sequência previsível.","x":"A mudança de plano do swing entre a bola plana e a de topspin.","i":"Qual das duas trajetórias é a preferida do jogador. As duas convivem — não se elege uma como a certa."},{"c":"FB009","n":"BH Slice Cruzado","f":"FB","e":["A","C"],"o":"Slice de BH como ferramenta defensiva e de variação.","m":"Jogadores trocam BH slice na cruzada. Foco em: trajetória baixa sobre a rede, bola que desliza no piso, profundidade no fundo. Não deve subir mais de 1m acima da rede.","g":"5-7 min","r":"Bola alimentada alta, sem deslocamento.","p":"Slice de defesa em bola profunda com deslocamento para trás.","x":"Ângulo da raquete e permanência do corpo baixo na saída.","i":"A altura da bola sobre a rede. Slice defensivo alto está cumprindo sua função — ganhar tempo."},{"c":"FB010","n":"FH e BH com Recuperação ao Centro","f":"FB","e":["A","C"],"o":"Hábito de recuperação ao centro após cada golpe.","m":"Jogadores trocam bolas na cruzada mas após cada golpe devem tocar o cone no centro da linha de base antes de se mover para o próximo golpe.","g":"5-7 min","r":"Reduzir o ritmo da troca; marcar o ponto central com cone.","p":"Aumentar o ritmo e o afastamento lateral da alimentação.","x":"O último passo de recuperação — se ele acontece antes da bola do adversário sair.","i":"A qualidade do golpe. A métrica aqui é o retorno ao centro; golpe imperfeito com recuperação correta é execução correta."},{"c":"FB011","n":"FH Open Stance","f":"FB","e":["A","C"],"o":"FH com stance aberto - padrão do tênis moderno.","m":"Treinador alimenta bolas forçando stance aberto. Foco na rotação completa dos quadris e ombros. Peso transfere do pé traseiro para o pé da frente durante o swing.","g":"6 séries de 8 bolas","r":"Posição de contato marcada no chão; alimentação parada.","p":"Bola em movimento lateral, obrigando ajuste da base em deslocamento.","x":"Base de apoio e rotação do quadril sem perder o eixo.","i":"A stance fechada quando ela aparece. Open stance é padrão, não regra única — em bola curta a fechada continua sendo a melhor escolha."},{"c":"FB012","n":"BH Closed Stance","f":"FB","e":["A","C"],"o":"BH com stance fechado - base da técnica moderna.","m":"Treinador alimenta bolas centrais para BH com stance fechado. Atentar ao cruzamento do pé de frente. Rotação do ombro deve ser completa.","g":"6 séries de 8 bolas","r":"Alimentação parada com pé de apoio marcado.","p":"Bola com deslocamento e alternância de profundidade.","x":"Entrada do pé da frente e transferência de peso na direção do golpe.","i":"Open stance de backhand quando aparece sob pressão. Sob pressão ela é a resposta correta."},{"c":"FB013","n":"Voleio FH - Bloqueio","f":"FB","e":["A","C"],"o":"Voleio de FH como bloqueio com direção definida.","m":"Jogador na linha de serviço. Treinador alimenta bolas para voleio de FH. Foco em: split step, punho firme, bloqueio sem swing, direção definida antes do contato.","g":"6 séries de 8 voleios","r":"Bola lançada com a mão, à altura do peito.","p":"Voleio com deslocamento lateral prévio e alvo de direção definido.","x":"Punho firme e contato à frente, com o corpo entrando na bola.","i":"O tamanho da preparação. Voleio curto demais é raro; corrigir excesso vem depois de existir o bloqueio."},{"c":"FB014","n":"Voleio BH - Bloqueio","f":"FB","e":["A","C"],"o":"Voleio de BH com punho firme e direção.","m":"Mesma estrutura do FB013 com BH. Braço estendido para o lado esquerdo (destros), punho firme acima do pulso, ângulo de raquete levemente aberto.","g":"6 séries de 8 voleios","r":"Bola lançada com a mão; voleio a uma mão com apoio da outra na raquete.","p":"Voleio baixo e voleio alto alternados, com direção comandada.","x":"Firmeza do punho e ombro à frente no contato.","i":"Direção nas primeiras séries. Primeiro o bloqueio existe; depois ele aponta."},{"c":"FB015","n":"Smash Central","f":"FB","e":["A","C"],"o":"Smash frontal como golpe decisivo na rede.","m":"Treinador alimenta lobs centrais para smash. Apontar com o braço livre, posicionar de lado, contato com braço estendido acima da cabeça. Direção com alvo.","g":"6 séries de 6 smashes","r":"Bola lançada com a mão, sem deslocamento, com o jogador já posicionado.","p":"Lob alimentado profundo, obrigando recuo com passo cruzado antes do smash.","x":"Posicionamento sob a bola e o braço não-dominante apontando para acompanhar a trajetória.","i":"A força. Smash mal posicionado não se resolve batendo mais forte — se resolve chegando antes."},{"c":"FB016","n":"Lob Defensivo","f":"FB","e":["A","C"],"o":"Lob como resposta a bolas de pressão com oponente na rede.","m":"Treinador na rede alimenta bolas rápidas. Jogador executa lob defensivo: alto (pelo menos 2m acima do oponente), profundo (último metro do fundo), preferencialmente para o BH do adversário.","g":"6 séries de 6 lobs","r":"Alimentação lenta e alta, com o treinador na rede sem finalizar.","p":"Lob sob pressão real, com adversário buscando o smash.","x":"Abertura da face e permanência do corpo baixo no contato.","i":"A profundidade nas primeiras repetições. Lob curto é erro de altura, não de intenção — o jogador acertou a decisão."},{"c":"FB017","n":"Drop Shot pelo FH","f":"FB","e":["A","C"],"o":"Drop shot pelo FH com disfarce e precisão.","m":"Treinador alimenta bolas de profundidade média. Preparação idêntica ao FH normal, ação de segurar a raquete no contato criando efeito cortado curto. Alvo: primeiro metro após a rede.","g":"6 séries de 6 drop shots","r":"Alimentação de bola curta e lenta, com o jogador já dentro da quadra.","p":"Disfarce: preparação idêntica à do golpe de base até o instante do contato.","x":"Toque leve e desaceleração da raquete no contato.","i":"A quantidade de drop shots que caem na rede no início. O gesto é de precisão fina e leva semanas."},{"c":"FB018","n":"Drop Shot pelo BH","f":"FB","e":["A","C"],"o":"Drop shot pelo BH com disfarce e controle.","m":"Mesma filosofia do FB017 com BH. A raquete acompanha a bola brevemente em vez de atravessa-lá. Alvo: quina da rede ou curto cruzado.","g":"6 séries de 6 drop shots","r":"Bola alimentada alta e lenta pelo lado do backhand.","p":"Drop shot a partir de bola profunda, com deslocamento para dentro da quadra.","x":"Ângulo aberto da face e controle da desaceleração.","i":"A escolha do momento. Aqui se treina o gesto; quando usar é assunto da família tática."},{"c":"FB019","n":"Passada Cruzada","f":"FB","e":["A","C"],"o":"Passing shot cruzado com adversário na rede.","m":"Treinador na rede alimenta bolas de borda. Jogador executa passada cruzada com FH ou BH. Bola baixa sobre a rede, com bom ângulo e profundidade.","g":"6 séries de 6 passadas","r":"Treinador na rede sem interceptar; bola alimentada de posição fixa.","p":"Adversário real na rede buscando o voleio de finalização.","x":"Contato à frente e ombro fechado para segurar a bola dentro do ângulo.","i":"Passadas que o adversário alcança. A passada cruzada correta pode ser voleada — a decisão continua certa."},{"c":"FB020","n":"Passada Paralela","f":"FB","e":["A","C"],"o":"Passing shot paralelo como alternativa tática.","m":"Treinador na rede alimenta bolas centrais. Jogador executa passada paralela. Bola baixa pelo lado do oponente, profunda. Timing crítico: bater cedo.","g":"6 séries de 6 passadas","r":"Adversário na rede parado do lado oposto.","p":"Adversário coberto na paralela, obrigando disfarce da direção.","x":"Preparação idêntica à da cruzada até o contato, e a linha do ombro.","i":"A taxa de erro para fora. A paralela é o tiro mais estreito da quadra — o erro é do risco escolhido, não do gesto."},{"c":"FB021","n":"Approach FH Paralelo","f":"FB","e":["A","C"],"o":"Approach de FH pela paralela como subida eficiente.","m":"Treinador alimenta bolas curtas. Jogador avança e executa FH approach pela paralela profundo e baixo. Sobe a rede para posição de voleio. Foco no split step após o approach. J","g":"6 séries de 6 approaches","r":"Bola curta alimentada de cesta com o jogador já em movimento.","p":"Approach seguido de voleio real com o ponto disputado até o fim.","x":"Subida em movimento, sem parar após o contato, e altura baixa da bola de approach.","i":"A potência do approach. Approach é bola de posicionamento — pedir força aqui converte um approach em ataque e tira o jogador da rede."},{"c":"FB022","n":"Approach BH Cruzado","f":"FB","e":["A","C"],"o":"Approach de BH cruzado para subida à rede.","m":"Treinador alimenta bolas curtas para o BH. Jogador executa BH approach cruzado, profundo, e sobe à rede. Split step antes do voleio.","g":"6 séries de 6 approaches J","r":"Aproximação sem deslocamento; alimentação parada em meia quadra.","p":"Approach cruzado seguido de cobertura da paralela na rede.","x":"Continuidade do deslocamento e altura da bola sobre a rede.","i":"A direção quando o jogador está atrasado. Chegar atrasado e subir mesmo assim é o erro real; a direção é secundário."},{"c":"FB023","n":"Devolução - Bloco","f":"FB","e":["A","C"],"o":"Devolução segura como primeira resposta ao saque.","m":"Treinador saca com velocidade moderada de ambos os lados. Jogador usa devolução de bloco: swing curto, contato firme, redirecionando com profundidade. Sem tentar acelerar.","g":"8-12 devoluções por lado","r":"Saque alimentado à meia velocidade ou por lançamento de mão.","p":"Saque real em velocidade de jogo, alternando lados.","x":"Preparação curta e split step no instante do contato do sacador.","i":"A profundidade da devolução. Bloco que entra já cumpriu o objetivo do exercício."},{"c":"FB024","n":"Devolução - Ataque FH","f":"FB","e":["A","C"],"o":"Devolução agressiva de FH contra saques abertos.","m":"Treinador saca aberto no AC. Jogador usa devolução de FH agressiva: swing completo, intenção de cruzada profunda ou inside out. Decisão da direção antes do saque.","g":"8-12 devoluções","r":"Saque à meia velocidade e alvo amplo.","p":"Devolução de ataque seguida da primeira bola disputada.","x":"Entrada do corpo para dentro da quadra e ponto de contato à frente da linha.","i":"O erro para fora. Devolução de ataque erra — se ela nunca erra, não é ataque."},{"c":"FB025","n":"Saque Flat - T","f":"FB","e":["A","C"],"o":"Saque flat com precisão no T.","m":"Jogador executa saques flat com alvo no T. Foco: lançamento acima e levemente à frente, contato no ponto mais alto, pronação natural. 5 saques por série.","g":"8-12 séries de 5 saques","r":"Saque a partir da posição de trofeu, sem movimento completo.","p":"Reduzir o alvo do T e registrar o percentual por série.","x":"Lançamento consistente e flexão de joelhos na carga.","i":"O percentual nas primeiras séries e a flexão exagerada — a referência é 65 a 67 graus, não o agachamento máximo."},{"c":"FB026","n":"Saque Flat - Aberto","f":"FB","e":["A","C"],"o":"Saque flat com precisão aberto.","m":"Mesmo formato do FB025 com alvo no canto externo. Trabalhar dos dois lados (DC e AC).","g":"8-12 séries de 5 saques","r":"Alvo ampliado; saque de posição de trofeu.","p":"Alvo reduzido, com registro de percentual e alternância com o T.","x":"Lançamento mais à frente e à direita, e a linha do ombro na saída.","i":"A força do saque. Velocidade de braço, não força de braço — a diferença aparece no som, não no esforço."},{"c":"FB027","n":"Saque Kick","f":"FB","e":["A","C"],"o":"Saque com efeito kick como 2º saque consistente.","m":"Lançamento mais atrás da cabeça, contato na posição 11h, escovada de baixo para cima e levemente para o lado. Bola deve saltar alto para o BH do adversário no AC.","g":"8-12 séries de 5 saques","r":"Movimento de kick sem bola, depois com bola sem alvo.","p":"Kick com alvo alto no quadrado e uso como segundo saque em ponto real.","x":"Trajetória da raquete de baixo para cima e o arqueamento das costas.","i":"A velocidade. O kick vive da altura sobre a rede e do salto após o quique — velocidade aqui é irrelevante."},{"c":"FB028","n":"Saque Slice","f":"FB","e":["A","C"],"o":"Saque slice para afastar o adversário.","m":"Lançamento levemente a direita (destros), contato na posição 3h, escovada lateral. Bola deve deslizar baixa e abrir o campo. Trabalhar dos dois lados.","g":"8-12 séries de 5 saques","r":"Sem bola primeiro; depois com alvo amplo no lado aberto.","p":"Slice aberto para tirar o adversário da quadra, seguido da primeira bola.","x":"Lançamento mais lateral e contato na lateral da bola.","i":"A profundidade. Slice curto e aberto que tira o adversário da quadra é um bom saque."},{"c":"FB029","n":"FH Shadow Drill","f":"FB","e":["A","C"],"o":"Fixar o padrão motor do FH sem a pressão da bola.","m":"Shadow swings de FH: preparação completa, rotação dos quadris antes dos ombros, ponto de contato à frente do corpo, finalização acima do ombro oposto. Treinador corrige o gesto.","g":"3 séries de 20 repetições","r":"Movimento fracionado em quatro tempos, com pausa em cada um.","p":"Movimento em velocidade real, com deslocamento antes de cada repetição.","x":"Sequência base de apoio → preparação → contato → terminação, sem a pressão da bola.","i":"Ritmo. Shadow lento e correto vale mais que shadow rápido e aproximado."},{"c":"FB030","n":"BH Shadow Drill","f":"FB","e":["A","C"],"o":"Fixar o padrão motor do BH sem a pressão da bola.","m":"Mesmo formato do FB029 com BH. Para dois mãos: início do movimento pelo braço não-dominante. Para uma mão: posição da pegada e extensão na finalização.","g":"3 séries de 20 repetições","r":"Movimento fracionado com pausa no ponto de contato imaginário.","p":"Shadow com deslocamento lateral e alternância de altura simulada.","x":"Coordenação entre rotação do tronco e chegada do braço.","i":"Detalhes finos de pegada. Shadow fixa o padrão amplo; a pegada se corrige com bola."},{"c":"IP001","n":"Saque e ponto","f":"IP","e":["A","C"],"o":"","m":"Saca e disputa o ponto imediatamente, sem troca de aquecimento prévia.","g":"4 séries de 6 pontos","r":"quadra reduzida, saque por baixo","p":"saque com alvo declarado antes","x":"rotina antes do saque, disputa até o fim","i":"qualidade técnica do saque"},{"c":"IP002","n":"Saque para dois alvos","f":"IP","e":["A"],"o":"","m":"Dois alvos amplos na área de saque; declara o alvo em voz alta antes de sacar.","g":"3 × 10 saques","r":"alvos maiores, sem declarar","p":"três alvos, um deles no corpo","x":"decisão fechada antes da rotina","i":"velocidade"},{"c":"IP003","n":"Saque + a bola seguinte","f":"IP","e":["A","C"],"o":"","m":"Saca, o professor devolve neutro, o aluno executa a primeira bola com intenção definida.","g":"4 × 8 sequências","r":"devolução lançada pelo professor","p":"devolução real variando os três caminhos","x":"intenção da primeira bola, recuperação após o saque","i":"o resultado do ponto"},{"c":"IP004","n":"Devolução e ponto","f":"IP","e":["A","C"],"o":"","m":"O ponto começa na devolução; sacador com saque controlado.","g":"4 × 6 pontos","r":"saque lançado por baixo","p":"sacador com saque pleno","x":"posição de espera e split","i":"potência da devolução"},{"c":"IP005","n":"Devolução com dois alvos","f":"IP","e":["A"],"o":"","m":"Devolve alternando alvo declarado antes do saque.","g":"3 × 10","r":"alvo único e amplo","p":"alvo escolhido só após ver a direção do saque","x":"direção com estrutura firme","i":"profundidade máxima"},{"c":"IP006","n":"Devolução + primeira bola","f":"IP","e":["A","C"],"o":"","m":"Devolve e executa a bola seguinte com intenção definida.","g":"4×8","r":"primeira bola livre","p":"primeira bola com alvo de pressão","x":"recuperação ao centro dinâmico entre as duas bolas","i":"o terceiro golpe"},{"c":"IP007","n":"Devolução entrando","f":"IP","e":["A","C"],"o":"","m":"Espera dentro da linha, bloqueia com direção e sai à frente.","g":"3 × 10","r":"segundo saque apenas","p":"primeiro saque forte","x":"timing do split no contato do sacador","i":"tamanho da preparação"},{"c":"IP008","n":"Devolução de trás com profundidade","f":"IP","e":["A","C"],"o":"","m":"Espera atrás, golpe pleno com alvo central profundo.","g":"3 × 10","r":"alvo mais curto","p":"alvo além da linha de saque com margem reduzida","x":"transferência de peso para dentro","i":"ângulo"},{"c":"IP009","n":"Saque aberto + quadra vazia","f":"IP","e":["A","C"],"o":"","m":"Saque aberto na quadra de iguais; ataca o espaço oposto na primeira bola.","g":"4×6","r":"professor devolve para o lado previsto","p":"devolução variando","x":"leitura do espaço criado","i":"velocidade do saque"},{"c":"IP010","n":"Saque no corpo + centro","f":"IP","e":["A","C"],"o":"","m":"Saque no corpo; primeira bola agressiva pelo centro, negando ângulo.","g":"4×6","r":"alvo central amplo","p":"exigir profundidade além da linha de saque","x":"posicionamento após o saque","i":"o resultado do ponto"},{"c":"IP011","n":"Saque fechado + paralela protegida","f":"IP","e":["C"],"o":"","m":"Saque fechado; primeira bola protegendo a paralela.","g":"3×8","r":"sem exigência de direção","p":"devolvedor instruído a atacar a paralela","x":"cobertura da rota provável","i":"potência"},{"c":"IP012","n":"Matriz três caminhos","f":"IP","e":["C"],"o":"","m":"A devolução volta cruzada, pelo meio ou paralela; a resposta está pré-resolvida para cada uma.","g":"6×6","r":"dois caminhos apenas","p":"o devolvedor escolhe livremente","x":"decisão instantânea, sem deliberar","i":"execução fina"},{"c":"IP013","n":"Matriz completa dos 18 cenários","f":"IP","e":["C"],"o":"","m":"Três direções de saque × dois lados × três caminhos de devolução.","g":"18 blocos de 4 pontos, distribuídos em duas semanas","r":"trabalhar seis cenários por vez","p":"encadear com a terceira bola","x":"o mapa estar pré-resolvido","i":"tudo o mais"},{"c":"IP014","n":"Saque indecifrável","f":"IP","e":["C"],"o":"","m":"Duas variações com armado idêntico; o parceiro tenta antecipar e declara antes do contato.","g":"3 × 12","r":"duas variações muito distintas","p":"três variações","x":"identidade do armado e do lançamento","i":"eficácia do saque"},{"c":"IP015","n":"Segundo saque com alvo","f":"IP","e":["A","C"],"o":"","m":"Apenas segundos saques, com alvo e plano declarados. Proibido jogar para “não errar”.","g":"4 × 10","r":"alvo amplo","p":"placar adverso simulado","x":"existência de intenção positiva","i":"duplas faltas nas primeiras sessões"},{"c":"IP016","n":"Saque + subida","f":"IP","e":["A","C"],"o":"","m":"Saque e subida imediata, com split na zona de voleio antes do golpe do adversário.","g":"3×8","r":"subir após a primeira bola","p":"contra devolvedor atacando","x":"timing do split na subida","i":"qualidade do voleio"},{"c":"IP017","n":"Devolução + subida","f":"IP","e":["A","C"],"o":"","m":"Devolução agressiva emendando avanço.","g":"3×8","r":"apenas em segundo saque","p":"em primeiro saque","x":"decisão de subir tomada antes da devolução","i":"o voleio"},{"c":"IP018","n":"Rodízio de início de ponto","f":"IP","e":["A"],"o":"","m":"Grupo: dois sacam, dois devolvem, troca a cada quatro pontos.","g":"20 min","r":"saques lançados","p":"com placar e consequência","x":"ritmo e engajamento de todos","i":"técnica fina"},{"c":"IP019","n":"Saque sob placar adverso","f":"IP","e":["C"],"o":"","m":"Sacar em 0-30 e 30-40, declarando direção e tipo antes.","g":"3×8","r":"só 30-40","p":"com público ou parceiro pressionando","x":"decisão fechada e não reaberta","i":"resultado"},{"c":"IP020","n":"Devolução contra três velocidades","f":"IP","e":["A","C"],"o":"","m":"O sacador varia entre lento, médio e forte sem avisar.","g":"3 × 12","r":"duas velocidades","p":"variando também direção e efeito","x":"ajuste de posição e de tamanho de preparação","i":"potência"},{"c":"JA001","n":"Ponto do saque","f":"JA","e":["A","C"],"o":"","m":"Todo ponto começa com saque real.","g":"10–15 pontos","r":"saque adaptado","p":"saque com plano declarado","x":"rotina","i":"técnica"},{"c":"JA002","n":"Ponto de quatro bolas","f":"JA","e":["A","C"],"o":"","m":"O ponto encerra na quarta bola; vence quem estiver melhor posicionado.","g":"12 pontos","r":"seis bolas","p":"três bolas","x":"intenção desde a primeira bola","i":"trocas longas"},{"c":"JA003","n":"Frente vale dobro","f":"JA","e":["A","C"],"o":"","m":"Ponto ganho à frente da linha de serviço vale dois.","g":"um set curto","r":"vale um e meio","p":"só pontua à frente","x":"disposição de subir","i":"qualidade do voleio"},{"c":"JA004","n":"Curta obrigatória","f":"JA","e":["A"],"o":"","m":"Toda bola curta recebida obriga a entrar e atacar.","g":"12 pontos","r":"obrigatório só em bola muito curta","p":"qualquer bola dentro da quadra","x":"reconhecimento","i":"erro no ataque"},{"c":"JA005","n":"Rei da quadra com saque","f":"JA","e":["A"],"o":"","m":"Rodízio com saque obrigatório a cada entrada.","g":"15 min","r":"entrada com bola lançada","p":"dois pontos para entrar","x":"ritmo","i":"técnica"},{"c":"JA006","n":"Classificar em voz alta","f":"JA","e":["A","C"],"o":"","m":"Diz “neutra”, “ataque” ou “defesa” antes de cada golpe.","g":"12 pontos","r":"só na primeira bola","p":"em todas, com o professor conferindo","x":"ler a bola, não o próprio estado","i":"execução"},{"c":"JA007","n":"Mudança de direção autorizada","f":"JA","e":["A","C"],"o":"","m":"Só pode mudar de direção se o deslocamento estiver induzindo.","g":"12 pontos","r":"o professor autoriza em voz alta","p":"o aluno julga sozinho","x":"geometria do deslocamento","i":"resultado"},{"c":"JA008","n":"Contato antecipado","f":"JA","e":["A","C"],"o":"","m":"Ponto perdido se golpear na descida da bola.","g":"10 pontos","r":"vale só no fundo","p":"vale em toda bola","x":"posição de espera mais dentro","i":"erros iniciais"},{"c":"JA009","n":"Placar adverso","f":"JA","e":["A","C"],"o":"","m":"O jogo começa 0-30 ou 2-4.","g":"2 sets curtos","r":"15-30","p":"0-40","x":"protocolo entre pontos","i":"o placar final"},{"c":"JA010","n":"Placar favorável a fechar","f":"JA","e":["A","C"],"o":"","m":"Começa 40-0 e precisa fechar.","g":"2 sets curtos","r":"40-15","p":"40-0 com dois break points salvos antes","x":"manter intenção com vantagem","i":"resultado"},{"c":"JA011","n":"Duas defesas","f":"JA","e":["A","C"],"o":"","m":"Defender alternando obrigatoriamente alta e acelerada.","g":"12 pontos","r":"alternância anunciada","p":"por chamada durante o ponto","x":"disponibilidade das duas opções","i":"qualidade fina"},{"c":"JA012","n":"Protocolo entre pontos","f":"JA","e":["A","C"],"o":"","m":"Ponto anulado se a rotina de quatro passos não for executada.","g":"um set","r":"só antes do saque","p":"também na devolução","x":"execução real, não mecânica","i":"o jogo"},{"c":"JA013","n":"Padrão obrigatório","f":"JA","e":["C"],"o":"","m":"Só pontua quem executar o padrão do dia.","g":"12 pontos","r":"dois padrões possíveis","p":"padrão único","x":"automatização","i":"o resto do ponto"},{"c":"JA014","n":"Set curto com tema","f":"JA","e":["A","C"],"o":"","m":"Set a 4 games com a regra do dia valendo.","g":"1–2 sets","r":"a 3 games","p":"com placar adverso somado","x":"transferência do tema para o jogo","i":"vitória"},{"c":"MV001","n":"Movimentação em X","f":"MV","e":["A","C"],"o":"Padrão de movimentação em X combinando defesa e ataque.","m":"Treinador lança 2 bolas profundas (defesa) e 2 curtas (ataque) alternando FH e BH. Jogador retorna sempre ao ponto central formando o X. Cones marcam os 4 pontos de chegada.","g":"4 séries de 8-12 bolas","r":"Reduzir a quatro bolas por série e ampliar o intervalo entre alimentações.","p":"Aumentar o ritmo da alimentação e retirar os cones de referência.","x":"A recuperação ao ponto central após cada golpe — esta é a métrica do exercício.","i":"A qualidade do golpe. Golpe médio com recuperação correta é execução correta aqui."},{"c":"MV002","n":"Movimentação em V Ofensivo","f":"MV","e":["A","C"],"o":"Padrão de deslocamento em V para bolas de ataque.","m":"Treinador lança bolas curtas. Jogador avança em diagonal, passa por trás do cone, golpeia em ataque e recupera em diagonal oposta formando o V.","g":"4 séries de 4-8 bolas","r":"Bola de ataque alimentada mais lenta e mais alta.","p":"Alternar bola de ataque e bola neutra sem aviso prévio.","x":"A geometria da entrada em V: entrar na diagonal, não de frente.","i":"O efeito da bola de ataque. Pedir mais spin para ela cair dentro converte ataque em controle."},{"c":"MV003","n":"Movimentação em V Defensivo","f":"MV","e":["A","C"],"o":"Padrão de deslocamento em V para bolas defensivas.","m":"Treinador lança bolas profundas. Jogador recua, passa pela frente do cone, golpeia em defesa (alto e fundo) e recupera em diagonal.","g":"4 séries de 4-8 bolas","r":"Reduzir a profundidade da alimentação; menos bolas por série.","p":"Alimentação mais profunda e angulada, forçando saída em corrida.","x":"A saída do V defensivo e o primeiro passo de retorno.","i":"A escolha entre defesa alta e defesa acelerada. As duas convivem — a função é parar o ataque, não devolver mais uma bola."},{"c":"MV004","n":"Spider Drill - 5 Pontos","f":"MV","e":["A","C"],"o":"Velocidade, aceleração e mudança de direção.","m":"5 bolas posicionadas: centro da base, ambos cantos do fundo e ambas posições de rede. Parte do centro, busca cada bola individualmente e retorna. Cronometrar.","g":"4 séries, 90 seg descanso","r":"Reduzir a três pontos e retirar o cronômetro.","p":"Cronometrar e registrar; competir contra a própria marca da semana anterior.","x":"Freada e mudança de direção no ponto de chegada.","i":"O tempo total nas primeiras semanas. Movimento eficiente primeiro; o cronômetro depois."},{"c":"MV005","n":"Skipping Lateral - FH","f":"MV","e":["A","C"],"o":"Coordenação e passadas de ajuste laterais com FH.","m":"Jogador faz skipping lateral por linha de 4 cones baixos e ao final executa FH. Foco na velocidade dos pés nos cones e na preparação da raquete ANTES de sair dos cones.","g":"4 séries de 4-6 bolas","r":"Sem bola, apenas o padrão de passos.","p":"Aumentar a distância lateral e a velocidade da alimentação.","x":"Passadas de ajuste curtas antes do contato — o último passo é o que decide o golpe.","i":"O golpe em si. Aqui se corrigem os pés; a raquete espera a sua vez."},{"c":"MV006","n":"Skipping Lateral - BH","f":"MV","e":["A","C"],"o":"Coordenação e passadas de ajuste com BH.","m":"Mesmo formato do MV005 com saída pelo BH. Cones levemente deslocados para o lado do BH.","g":"4 séries de 4-6 bolas","r":"Padrão de passos sem bola, em ritmo lento.","p":"Alternância de distância e alimentação sem aviso do lado.","x":"Ajuste final do apoio antes do contato de backhand.","i":"Consistência da bola. Este é um exercício de pés com bola, não de troca."},{"c":"MV007","n":"Zig Zag Frente e Costas","f":"MV","e":["A","C"],"o":"Coordenação para passadas de ajuste em múltiplos planos.","m":"Jogador faz zig zag: entra de frente entre os cones, sai de costas. Ao final executa FH ou BH. 4 cones baixos.","g":"4 séries de 4-6 bolas","r":"Reduzir o número de mudanças de plano por série.","p":"Acrescentar bola após cada zigue-zague, com direção comandada.","x":"Coordenação entre planos de deslocamento — frente, trás e lateral na mesma série.","i":"Velocidade. Coordenação antes de velocidade, sempre."},{"c":"MV008","n":"Entrar e Sair - Ajuste de Passadas","f":"MV","e":["A","C"],"o":"Ajuste de passadas para frente e para trás nos golpes de base.","m":"Em rally cruzado, ambos devem sempre entrar ou sair para cada golpe - sem ficar parados nem só deslocar lateralmente.","g":"5-7 min por cruzada","r":"Alimentação de cesta com distância fixa entre as bolas.","p":"Troca livre na cruzada, com o treinador variando a profundidade sem aviso.","x":"O ajuste para frente e para trás — entrar na bola curta e sair da bola profunda.","i":"A direção. Aqui só existe a cruzada; a decisão de direção não está em jogo."},{"c":"MV009","n":"2x1 - Mudança de Direção","f":"MV","e":["A","C"],"o":"Mudança de direção sob pressão de dois golpes para um lado e um para o outro.","m":"Jogador A golpeia 2 cruzadas e 1 paralela. Jogador B golpeia somente na cruzada. Alternar papéis.","g":"5-7 min, alternar papéis","r":"Ritmo reduzido; o jogador do lado único define o ritmo.","p":"Aumentar o ritmo e reduzir o tempo entre as bolas.","x":"A mudança de direção sob deslocamento: geometria dos apoios antes da bola.","i":"O cansaço do jogador do lado único. A fadiga é parte do desenho do exercício."},{"c":"MV010","n":"1x1 - Ritmo de Mudança","f":"MV","e":["A","C"],"o":"Mudança de direção em ritmo mais alto.","m":"Jogador A golpeia 1 cruzada e 1 paralela alternando. Jogador B responde somente cruzado. Ritmo mais alto que o 2x1.","g":"5-7 min, alternar papéis","r":"Reduzir o ritmo e a distância lateral.","p":"Ritmo alto com contagem de trocas antes do erro.","x":"Frequência de passos entre golpes.","i":"Erros que aparecem no fim da série. Eles são informação sobre condicionamento, não sobre técnica."},{"c":"MV011","n":"2x2 - Comando pelo FH","f":"MV","e":["A","C"],"o":"Comando tático usando FH para dois lados.","m":"Jogador A golpeia 2 bolas para cada lado (FH ou BH). Jogador B golpeia somente no centro.","g":"5-7 min, alternar","r":"Reduzir a exigência de deslocamento do jogador comandado.","p":"Comando livre, com o jogador do FH decidindo a direção em tempo real.","x":"A posição de espera que permite o FH invertido.","i":"O backhand do jogador que comanda. Neste exercício ele não existe."},{"c":"MV012","n":"Corrida FH - Cruzada","f":"MV","e":["A","C"],"o":"FH na corrida com saída para a cruzada profunda.","m":"Jogador simula BH e recebe FH na corrida. Bola golpeada na cruzada: funda, plana, sem ângulo excessivo.","g":"6 séries de 4 bolas","r":"Reduzir a distância da corrida; alimentação mais lenta.","p":"Duas bolas em corrida seguidas antes da saída cruzada.","x":"O apoio externo na saída e o equilíbrio no contato em corrida.","i":"A profundidade. Bola em corrida raramente é profunda — exigir isso quebra o equilíbrio do golpe."},{"c":"MV013","n":"Corrida BH - Cruzada","f":"MV","e":["A","C"],"o":"BH na corrida com saída para a cruzada profunda.","m":"Jogador simula FH e recebe BH na corrida. Bola cruzada, funda, sem ângulo excessivo.","g":"6 séries de 4 bolas","r":"Distância reduzida e alimentação alta.","p":"Corrida mais longa com recuperação imediata para a bola seguinte.","x":"Equilíbrio no contato e o apoio de freada.","i":"A altura da bola de saída. Bola alta na corrida é a resposta correta — ganha tempo."},{"c":"MV014","n":"Corrida FH - Paralela","f":"MV","e":["A","C"],"o":"FH na corrida com saída para a paralela.","m":"Jogador simula BH e recebe FH na corrida. Bola golpeada na paralela: timing de contato mais cedo que o normal.","g":"6 séries de 4 bolas","r":"Reduzir a distância e alimentar bola mais alta.","p":"Corrida em velocidade real com alvo estreito na paralela.","x":"Fechamento do ombro em desequilíbrio — a paralela em corrida exige mais rotação, não menos.","i":"A taxa de erro. Paralela em corrida é jogada de risco assumido."},{"c":"MV015","n":"Corrida BH - Paralela","f":"MV","e":["A","C"],"o":"BH na corrida com saída para a paralela.","m":"Jogador simula FH e recebe BH na corrida para a paralela. Timing preciso essencial para dois mãos.","g":"6 séries de 4 bolas","r":"Alimentação lenta e distância curta.","p":"Corrida longa com saída paralela e recuperação para a bola seguinte.","x":"Estabilidade do tronco no contato fora de equilíbrio.","i":"A comparação com a versão de forehand. São golpes diferentes com exigências diferentes."},{"c":"MV016","n":"Figura 8","f":"MV","e":["A","C"],"o":"Padrão de movimentação em figura 8 com golpes em ambos os lados.","m":"Dois cones posicionados. Jogador percorre figura 8 ao redor dos cones, recebendo FH no cone esquerdo e BH no direito.","g":"4 séries de 8 bolas","r":"Reduzir para quatro bolas e ampliar o intervalo.","p":"Aumentar o ritmo e acrescentar variação de altura.","x":"A curva do deslocamento — a figura 8 se perde quando o jogador anda em linha reta.","i":"A qualidade técnica dos golpes. O desenho do deslocamento é o objeto aqui."},{"c":"MV017","n":"Laterais com Escadinha - FH","f":"MV","e":["A","C"],"o":"Coordenação de pés laterais com escadinha e finalização de FH.","m":"Jogador percorre escadinha lateral e ao final executa FH. Velocidade máxima na escadinha, desaceleração controlada antes do golpe.","g":"4 séries de 6 bolas","r":"Escadinha sem bola; depois escadinha com bola alimentada parada.","p":"Escadinha em velocidade máxima seguida de golpe em deslocamento lateral.","x":"Transição da escadinha para o primeiro passo de aproximação da bola.","i":"A execução da escadinha em si depois que o padrão está estabelecido — o que interessa é a saída dela."},{"c":"MV018","n":"Laterais com Escadinha - BH","f":"MV","e":["A","C"],"o":"Coordenação de pés laterais com escadinha e finalização de BH.","m":"Mesmo formato do MV017 com BH. Atletas destros tendem a ter mais dificuldade neste lado.","g":"4 séries de 6 bolas","r":"Padrão de escadinha isolado, sem finalização.","p":"Escadinha rápida com finalização de backhand em bola em movimento.","x":"A saída da escadinha para o apoio de golpe.","i":"Erros do golpe final nas primeiras séries. O foco é a transição."},{"c":"MV019","n":"Defesa e Transição para Ataque","f":"MV","e":["A","C"],"o":"Transição da posição defensiva para a ofensiva em sequência.","m":"Treinador lança 2 bolas profundas (defesa) seguidas de 1 bola curta (transição). Jogador deve reconhecer a mudança e acelerar na bola de transição.","g":"4 séries de 6 bolas","r":"Separar as duas fases: primeiro a defesa, depois o ataque, em séries distintas.","p":"Sequência contínua com número variável de bolas defensivas antes da virada.","x":"O momento da virada — quando a bola do adversário permite sair da defesa.","i":"A execução do golpe de ataque. Aqui se corrige o reconhecimento do momento, não o golpe."},{"c":"MV020","n":"Triângulo - 3 Posições de Quadra","f":"MV","e":["A","C"],"o":"Agilidade entre 3 posições táticas: base, meia quadra e rede.","m":"3 cones em triângulo. Treinador sinaliza e jogador corre para a posição correspondente. Ao chegar, executa o golpe adequado para aquela posição.","g":"4 séries de 9 movimentações","r":"Reduzir a duas posições; retirar a pressão de tempo.","p":"Acrescentar bola em cada posição e cronometrar o circuito.","x":"Transição entre as três alturas de quadra — base, meia quadra e rede exigem apoios diferentes.","i":"O golpe executado em cada posição. O objeto é o trânsito entre elas."},{"c":"MV021","n":"Split Step - Timing de Reação","f":"MV","e":["A","C"],"o":"Timing correto do split step em relação ao contato do adversário.","m":"Treinador executa golpe. No momento exato do contato, jogador faz split step. Repetir com variação de posição.","g":"3 séries de 20 repetições","r":"Split step sem bola, no comando de voz do treinador.","p":"Split step com bola em velocidade real e direção imprevisível.","x":"O instante do split — ele acontece no contato do adversário, não depois.","i":"A altura do salto. Split step alto é split step lento."},{"c":"MV022","n":"Recuperação Lateral Rápida","f":"MV","e":["A","C"],"o":"Velocidade de recuperação lateral após golpes defensivos extremos.","m":"Treinador lança série de bolas alternando entre os dois lados extremos. Jogador deve recuperar o máximo possível entre golpes. Intensidade alta.","g":"4 séries de 6 bolas, 60 seg descanso","r":"Reduzir a amplitude do deslocamento defensivo.","p":"Duas recuperações extremas consecutivas antes do fim da série.","x":"O passo cruzado de saída da posição extrema.","i":"A qualidade da bola defensiva. Sair viva já é o resultado."},{"c":"MV023","n":"Avanço Diagonal - FH","f":"MV","e":["A","C"],"o":"Avanço diagonal em direção a bola curta com FH.","m":"Treinador alimenta bolas curtas em diagonal. Jogador avança em diagonal, executa FH approach profundo e sobe à rede.","g":"6 séries de 6 approaches J","r":"Bola curta alimentada com o jogador já em movimento.","p":"Bola curta imprevisível, alimentada durante uma troca.","x":"A diagonal de entrada — avanço em linha reta chega atrasado.","i":"O golpe de approach. O objeto é a trajetória do deslocamento."},{"c":"MV024","n":"Avanço Diagonal - BH","f":"MV","e":["A","C"],"o":"Avanço diagonal em direção a bola curta com BH.","m":"Mesma estrutura do MV023 com BH. O avanço diagonal para o BH é menos natural para a maioria dos atletas.","g":"6 séries de 6 approaches J","r":"Alimentação parada em meia quadra.","p":"Bola curta surpresa dentro de uma troca cruzada.","x":"A entrada diagonal pelo lado do backhand e o apoio no contato.","i":"A comparação de eficiência com o lado do forehand. São entradas diferentes."},{"c":"MV025","n":"Quadra Inteira - Cobertura Total","f":"MV","e":["A","C"],"o":"Cobrir toda a quadra em sequência de alta intensidade.","m":"Treinador lança 6 bolas em ordem imprevisível: 2 cruzadas, 2 paralelas, 1 curta, 1 lob. Jogador cobre todas.","g":"4 séries de 6 bolas, 90 seg descanso","r":"Reduzir para quatro bolas por série e ampliar o descanso.","p":"Seis bolas em máxima amplitude com descanso reduzido.","x":"Economia de deslocamento — quem cobre a quadra inteira o faz com menos passos, não com mais velocidade.","i":"Erros técnicos sob fadiga extrema. Eles são o custo da carga e não indicam lacuna técnica."},{"c":"PDB001","n":"Mudança de Direção - FH","f":"PDB","e":["A","C"],"o":"FH com trajetória plana e mudança de direção.","m":"Jogador a direita recebe 4 bolas alternando cruzada e paralela de FH. Trajetória plana, spin mínimo, transferir peso para frente.","g":"6-8 séries de 4 bolas","r":"Duas bolas por série com alimentação mais lenta.","p":"Seis bolas com alimentação em ritmo real e alvo estreito.","x":"Transferência de peso para frente e trajetória plana da bola.","i":"O efeito. Este é um exercício de bola plana — pedir mais topspin descaracteriza o objetivo."},{"c":"PDB002","n":"Mudança de Direção - BH","f":"PDB","e":["A","C"],"o":"BH com trajetória plana e mudança de direção.","m":"Jogador a esquerda recebe 4 bolas alternando cruzada e paralela de BH. Mesmo princípio: entrar, transferir, trajetória plana.","g":"6-8 séries de 4 bolas","r":"Alimentação parada, sem deslocamento entre as bolas.","p":"Ritmo alto com mudança de direção comandada em tempo real.","x":"Estabilidade do apoio na mudança de direção do backhand.","i":"A profundidade. Velocidade da bola no ar é a medida aqui."},{"c":"PDB003","n":"Mudança de Direção - Centro FH","f":"PDB","e":["A","C"],"o":"FH para os dois cantos a partir do centro.","m":"Jogador no centro recebe 4 bolas alternando entre os dois cantos com FH. Trajetória plana, retornar ao cone central.","g":"6-8 séries de 4 bolas","r":"Alternância previsível entre os dois cantos.","p":"Cantos definidos por comando do treinador durante a série.","x":"A posição de espera central que permite atender aos dois lados.","i":"A recuperação perfeita ao centro. Em bola de pressão a recuperação é parcial e isso é correto."},{"c":"PDB004","n":"Corrida FH - Saída Cruzada","f":"PDB","e":["A","C"],"o":"FH na corrida com saída para a cruzada profunda.","m":"Simula BH, recebe FH na corrida. Bola cruzada, plana, profunda, sem ângulo excessivo.","g":"6-8 séries de 4 bolas","r":"Corrida curta com alimentação alta.","p":"Corrida longa em ritmo real, com recuperação para a bola seguinte.","x":"O apoio externo de freada e o equilíbrio no contato.","i":"A profundidade da saída cruzada em corrida máxima."},{"c":"PDB005","n":"Corrida BH - Saída Cruzada","f":"PDB","e":["A","C"],"o":"BH na corrida com saída para a cruzada profunda.","m":"Simula FH, recebe BH na corrida. Bola cruzada, plana, profunda.","g":"6-8 séries de 4 bolas","r":"Distância reduzida; bola mais alta.","p":"Corrida longa com duas bolas consecutivas.","x":"Estabilidade do tronco no backhand em deslocamento.","i":"A velocidade da bola de saída. Em corrida, entrar já é o resultado."},{"c":"PDB006","n":"Corrida FH - Saída Paralela","f":"PDB","e":["A","C"],"o":"FH na corrida com saída para a paralela.","m":"Simula BH, recebe FH na corrida. Timing de contato mais cedo que o normal.","g":"6-8 séries de 4 bolas","r":"Corrida curta com alvo amplo.","p":"Corrida máxima com alvo estreito na paralela.","x":"Fechamento do ombro em desequilíbrio — a paralela exige mais rotação.","i":"A taxa de erro. Paralela em corrida é jogada de risco assumido."},{"c":"PDB007","n":"Corrida BH - Saída Paralela","f":"PDB","e":["A","C"],"o":"BH na corrida com saída para a paralela.","m":"Simula FH, recebe BH na corrida para paralela. Quadris devem rodar completamente.","g":"6-8 séries de 4 bolas","r":"Alimentação lenta e distância curta.","p":"Ritmo real com recuperação obrigatória após a saída.","x":"Extensão do braço na direção da paralela sem abrir o ombro cedo.","i":"A comparação com a paralela de forehand."},{"c":"PDB008","n":"Corrida FH Cruzada mais Mudança Paralela","f":"PDB","e":["A","C"],"o":"Corrida FH cruzado mais mudança para paralela.","m":"Corre para FH cruzado na corrida, recupera, recebe mais uma bola para FH paralelo.","g":"6-8 séries de 4 bolas","r":"Separar em dois exercícios: primeiro a corrida, depois a mudança.","p":"Sequência contínua em ritmo real com alvo estreito.","x":"A recuperação entre a corrida e a mudança — é ela que viabiliza a segunda bola.","i":"O erro da bola de mudança. É a bola de maior exigência do padrão."},{"c":"PDB009","n":"Corrida BH mais Inside In","f":"PDB","e":["A","C"],"o":"BH cruzado na corrida mais inside in.","m":"BH na corrida cruzado, recuperação, FH inside in como finalização.","g":"6-8 séries de 4 bolas","r":"Bola de inside in alimentada de posição fixa.","p":"Sequência completa em ritmo real, com o ponto disputado após.","x":"O deslocamento lateral que abre espaço para o forehand invertido.","i":"A velocidade do backhand de abertura."},{"c":"PDB010","n":"Abertura Centro FH mais Inside Out","f":"PDB","e":["A","C"],"o":"FH cruzado e pressão com inside out.","m":"FH próximo ao centro abre pela cruzada; em seguida bola central para inside out. Ambas planas.","g":"6-8 séries de 6 bolas","r":"Quatro bolas por série com alimentação lenta.","p":"Seis bolas em ritmo real com adversário ativo.","x":"A posição que torna o inside out disponível.","i":"A recuperação central completa entre as bolas."},{"c":"PDB011","n":"Abertura FH Cruzado mais Mudança","f":"PDB","e":["A","C"],"o":"FH cruzado e mudança de direção.","m":"FH cruzado profundo para deslocar mais bola mais central para mudança de direção.","g":"6-8 séries de 6 bolas","r":"Mudança anunciada antes da série.","p":"Momento da mudança decidido pelo jogador.","x":"O reconhecimento da bola que autoriza a mudança de direção.","i":"Qual bola foi escolhida para mudar, quando a geometria do deslocamento estava correta."},{"c":"PDB012","n":"Abertura BH Cruzado mais FH Final","f":"PDB","e":["A","C"],"o":"BH cruzado e finalização com FH.","m":"BH cruzado para deslocar mais bola central para FH finalizar.","g":"6-8 séries de 6 bolas","r":"Bola de finalização alimentada pelo treinador.","p":"Padrão completo em ritmo real com adversário defendendo.","x":"A transição do backhand de construção para o forehand de finalização.","i":"O erro da finalização. Decisão certa, execução errada: corrige-se contato ou apoio."},{"c":"PDB013","n":"Abertura FH mais Approach Paralela","f":"PDB","e":["A","C"],"o":"FH cruzado mais approach pela paralela.","m":"FH cruzado fundo mais bola curta cruzada para approach pela paralela subindo a rede.","g":"6-8 séries de 6 bolas J","r":"Approach alimentado, sem a fase de abertura.","p":"Padrão completo seguido de voleio e ponto disputado.","x":"A continuidade do deslocamento entre a abertura e o approach.","i":"A potência do approach. Approach é bola de posicionamento."},{"c":"PDB014","n":"Abertura Inside Out mais Approach BH","f":"PDB","e":["A","C"],"o":"Inside out e approach de BH para a rede.","m":"FH inside out mais bola curta cruzada para BH approach e subida à rede.","g":"6-8 séries de 6 bolas J","r":"Inside out alimentado de posição fixa.","p":"Sequência completa com voleio de finalização.","x":"A leitura da bola curta que autoriza o approach de backhand.","i":"A direção do approach nas primeiras séries."},{"c":"PDB015","n":"Abertura FH mais Approach Central","f":"PDB","e":["A","C"],"o":"FH cruzado mais approach central.","m":"FH cruzado fundo mais bola curta central para FH approach no lado oposto.","g":"6-8 séries de 6 bolas J","r":"Approach central alimentado isoladamente.","p":"Sequência completa com adversário buscando a passada.","x":"A altura baixa do approach central e a chegada à rede.","i":"O ângulo. Approach central existe justamente para não dar ângulo."},{"c":"PDB016","n":"Inside Out mais Approach Central","f":"PDB","e":["A","C"],"o":"Inside out e approach central pelo FH.","m":"Inside out como abertura mais bola curta central para FH approach.","g":"6-8 séries de 6 bolas J","r":"Separar inside out e approach em séries distintas.","p":"Sequência contínua com ponto disputado na rede.","x":"O encadeamento entre o forehand invertido e a entrada para a rede.","i":"A qualidade do voleio final."},{"c":"PDB017","n":"Inside Out mais Inside In mais Rede","f":"PDB","e":["A","C"],"o":"Dois FH agressivos e chegada à rede.","m":"Inside out mais inside in já avançando a rede. Ambas as bolas rápidas.","g":"6-8 séries de 6 bolas","r":"Duas bolas em vez de três; sem a chegada à rede.","p":"Sequência completa em ritmo real com adversário defendendo.","x":"A manutenção do equilíbrio entre dois forehands agressivos consecutivos.","i":"O erro no terceiro tempo. É o padrão de maior carga técnica da série."},{"c":"PDR001","n":"Subida FH Paralela mais Voleio BH","f":"PDR","e":["A","C"],"o":"Finalização na rede com voleio BH após approach FH paralelo.","m":"Bola curta, approach FH paralelo, voleio BH no lado oposto. Subida em movimento, split step antes do voleio.","g":"6-8 séries de 4 subidas J","r":"Approach alimentado com o jogador já em meia quadra.","p":"Ponto disputado após o voleio, com adversário buscando a passada.","x":"A sequência fluida entre approach, deslocamento e split step.","i":"A qualidade do approach quando o split step aconteceu no tempo certo."},{"c":"PDR002","n":"Subida FH Paralela mais Voleio FH","f":"PDR","e":["A","C"],"o":"Finalização com voleio FH após approach FH paralelo.","m":"Mesma subida do PDR001 com voleio FH. Foco em colocação, não potência.","g":"6-8 séries de 4 subidas J","r":"Approach parado; voleio alimentado com a mão.","p":"Sequência em velocidade real com direção do voleio comandada.","x":"A cobertura do lado do forehand após o approach paralelo.","i":"A direção do voleio nas primeiras séries."},{"c":"PDR003","n":"Subida BH Paralela mais Voleio FH","f":"PDR","e":["A","C"],"o":"Finalização com voleio FH após approach BH paralelo.","m":"Approach BH paralelo, voleio FH no lado oposto. Split step preciso após o approach de BH.","g":"6-8 séries de 4 subidas J","r":"Bola curta alimentada de cesta em meia quadra.","p":"Sequência completa com passada real do adversário.","x":"O deslocamento diagonal após o approach de backhand.","i":"A comparação de rendimento com o approach de forehand."},{"c":"PDR004","n":"Subida BH Paralela mais Voleio BH","f":"PDR","e":["A","C"],"o":"Finalização com voleio BH após approach BH paralelo.","m":"Approach BH paralelo, voleio BH. Exige bom posicionamento pós-approach.","g":"6-8 séries de 4 subidas J","r":"Voleio alimentado sem approach prévio.","p":"Sequência completa com dois voleios antes da finalização.","x":"A firmeza do punho no voleio de backhand em movimento.","i":"A profundidade do voleio. Voleio de finalização é ângulo, não profundidade."},{"c":"PDR005","n":"Subida FH Central Esq mais Voleio BH","f":"PDR","e":["A","C"],"o":"Approach FH pelo lado esquerdo, voleio BH.","m":"Bola curta no centro, approach FH pelo lado esquerdo, voleio BH no lado oposto.","g":"6-8 séries de 4 subidas J","r":"Approach central alimentado, sem deslocamento prévio.","p":"Sequência completa com ponto disputado.","x":"A posição de cobertura na rede após approach pelo centro.","i":"O ângulo do approach. Approach central não abre ângulo por definição."},{"c":"PDR006","n":"Subida FH Central Esq mais Voleio FH","f":"PDR","e":["A","C"],"o":"Approach FH pelo lado esquerdo, voleio FH.","m":"Mesma subida do PDR005 com voleio FH. Versão avançada: treinador decide o voleio no momento da subida.","g":"6-8 séries de 4 subidas J","r":"Alimentação parada em meia quadra.","p":"Ritmo real com direção do voleio decidida em tempo real.","x":"A antecipação da direção da passada do adversário.","i":"Erros de leitura nas primeiras séries. A leitura se constrói por repetição distribuída."},{"c":"PDR007","n":"Subida FH Central Dir mais Voleio BH","f":"PDR","e":["A","C"],"o":"Approach FH pelo lado direito, voleio BH.","m":"Bola curta no centro, approach FH pelo lado direito, voleio BH no lado oposto.","g":"6-8 séries de 4 subidas J","r":"Approach alimentado; voleio com bola lançada de mão.","p":"Sequência em velocidade real com adversário ativo.","x":"O deslocamento cruzado até a posição de voleio de backhand.","i":"A qualidade do approach quando a chegada à rede aconteceu no tempo."},{"c":"PDR008","n":"Subida FH Central Dir mais Voleio FH","f":"PDR","e":["A","C"],"o":"Ciclo completo: approach FH direito, voleio FH.","m":"Bola curta no centro, approach FH pelo lado direito, voleio FH. Completa o ciclo de 8 combinações PDR.","g":"6-8 séries de 4 subidas J","r":"Separar approach e voleio em séries distintas.","p":"Ciclo completo com dois voleios e smash de finalização.","x":"O encadeamento inteiro do ciclo, sem parada entre as fases.","i":"Erros isolados de cada fase. O objeto deste exercício é a continuidade."},{"c":"PDS001","n":"Saque mais 1 Bola DC","f":"PDS","e":["A","C"],"o":"Abertura do ponto no DC.","m":"Saque mais 1ª bola com decisão tática. Posição do saque e da 1ª bola variam. Decisão ANTES do saque.","g":"8-12 séries de 2 bolas","r":"Saque à meia velocidade; direção da primeira bola anunciada.","p":"Saque real com o ponto disputado após a primeira bola.","x":"A decisão tomada antes do saque e a recuperação para dentro da quadra.","i":"O percentual de primeiro saque. O objeto é o encadeamento saque–primeira bola."},{"c":"PDS002","n":"Saque mais 1 Bola AC","f":"PDS","e":["A","C"],"o":"Abertura do ponto no AC.","m":"Mesmo formato do PDS001 no AC. Saque aberto vai para o BH do adversário.","g":"8-12 séries de 2 bolas","r":"Alvo do saque ampliado.","p":"Alvo estreito com registro do percentual do padrão completo.","x":"A adaptação da geometria do padrão ao lado da vantagem.","i":"A transposição direta do padrão do lado da igualdade."},{"c":"PDS003","n":"DC Aberto - FH Centro - Inside","f":"PDS","e":["A","C"],"o":"Saque aberto DC, FH centro, inside out ou in.","m":"Saque aberto, 1ª bola central de FH, 2a bola inside out ou in como finalização.","g":"8-12 séries de 3 bolas","r":"Duas bolas em vez de três; decisão anunciada.","p":"Três bolas com decisão em tempo real na terceira.","x":"A posição de espera que mantém as duas saídas — inside out e inside in — disponíveis.","i":"Qual das duas saídas foi escolhida. Ambas são corretas se a leitura estava certa."},{"c":"PDS004","n":"DC Aberto - FH Direito - Inside In","f":"PDS","e":["A","C"],"o":"Saque aberto DC, FH direito, inside in.","m":"Saque aberto, 1ª bola FH direito, inside in como finalização.","g":"8-12 séries de 3 bolas","r":"Alimentação da segunda bola pelo treinador.","p":"Padrão completo com adversário defendendo de verdade.","x":"O fechamento do ombro no inside in.","i":"O erro para fora do inside in. É o tiro mais estreito do padrão."},{"c":"PDS005","n":"DC Aberto - FH Cruzado - BH/Inside Out","f":"PDS","e":["A","C"],"o":"Saque aberto DC, FH cruzado, finalização variada.","m":"Saque aberto, FH cruzado, BH cruzado ou inside out como finalização.","g":"8-12 séries de 3 bolas","r":"Finalização única e anunciada.","p":"Finalização escolhida em tempo real entre as duas opções.","x":"A leitura da posição do adversário após o forehand cruzado.","i":"A opção escolhida, quando a leitura estava correta."},{"c":"PDS006","n":"DC Aberto - BH - FH/Inside In","f":"PDS","e":["A","C"],"o":"Saque aberto DC, BH, finalização com FH.","m":"Saque aberto, BH, FH cruzado ou inside in. Saque abre, BH transita, FH finaliza.","g":"8-12 séries de 3 bolas","r":"Sequência com bolas alimentadas de posição fixa.","p":"Ritmo real com o ponto disputado após a terceira bola.","x":"A transição do backhand para o forehand de finalização.","i":"O erro da bola de finalização, quando o padrão foi construído corretamente."},{"c":"PDS007","n":"DC Fechado - BH - FH/Inside In","f":"PDS","e":["A","C"],"o":"Saque fechado DC, BH, finalização variada.","m":"Saque no T, 1ª bola BH, FH cruzado ou inside in.","g":"8-12 séries de 3 bolas","r":"Duas bolas com direção anunciada.","p":"Três bolas com decisão livre e adversário ativo.","x":"A adaptação ao ângulo do saque fechado.","i":"A velocidade do saque. Saque fechado vive de posicionamento."},{"c":"PDS008","n":"DC Fechado - BH - FH Variação","f":"PDS","e":["A","C"],"o":"Variação com decisão tática na 3a bola.","m":"Mesma estrutura do PDS007 com decisão em tempo real na 3a bola.","g":"8-12 séries de 3 bolas","r":"Variação suprimida: uma única finalização por série.","p":"Decisão livre na terceira bola, com registro do que foi escolhido.","x":"O tempo da decisão na terceira bola.","i":"A variante escolhida. O que se observa é se a decisão foi tomada a tempo."},{"c":"PDS009","n":"DC Fechado - BH - BH Cruzado/Inside Out","f":"PDS","e":["A","C"],"o":"Saque fechado DC, sequência de dois BH.","m":"Saque no T, BH, BH cruzado ou inside out como finalização.","g":"8-12 séries de 3 bolas","r":"Bolas alimentadas com direção fixa.","p":"Sequência real com adversário deslocando de verdade.","x":"A sustentação da qualidade em dois backhands consecutivos.","i":"A velocidade do primeiro backhand. Ele constrói, não finaliza."},{"c":"PDS010","n":"DC Fechado - BH - BH Paralelo/Inside In","f":"PDS","e":["A","C"],"o":"Saque fechado DC, finalização pela paralela de BH.","m":"Saque no T, BH, BH paralelo ou inside in. BH como arma de abertura E finalização.","g":"8-12 séries de 3 bolas","r":"Alvo ampliado na paralela de backhand.","p":"Alvo estreito com ponto disputado após a finalização.","x":"A rotação completa do quadril na paralela de backhand.","i":"A taxa de erro. A paralela de backhand é o tiro de menor margem do repertório."},{"c":"PDS011","n":"DC Fechado - FH Central - BH/Inside Out","f":"PDS","e":["A","C"],"o":"Saque fechado DC, FH central, finalização variada.","m":"Saque no T, FH central cruzado, BH cruzado ou inside out.","g":"8-12 séries de 3 bolas","r":"Finalização única e anunciada.","p":"Finalização decidida em tempo real.","x":"O forehand central como bola que retira ângulo do adversário.","i":"A profundidade da bola central quando ela cumpriu a função de neutralizar."},{"c":"PDS012","n":"DC Fechado - FH Central - Inside In/Out","f":"PDS","e":["A","C"],"o":"Saque fechado DC, FH central, inside in ou out.","m":"Saque no T, FH central, inside in ou inside out. O mais tecnicamente exigente da série PDS.","g":"8-12 séries de 3 bolas","r":"Uma das duas saídas por série.","p":"Escolha em tempo real com adversário se reposicionando.","x":"A posição do corpo que mantém as duas saídas disponíveis.","i":"Qual saída foi escolhida. O critério é a leitura, não a opção."},{"c":"RT001","n":"Chega antes da bola","f":"RT","e":["A"],"o":"","m":"Alvo no chão marcando onde os pés devem estar antes do quique.","g":"3 × 10","r":"bola mais lenta e alta","p":"bola mais rápida e profunda","x":"antecipação da saída","i":"o golpe"},{"c":"RT002","n":"Contato no topo","f":"RT","e":["A","C"],"o":"","m":"Golpear no instante em que a bola para no ar após o quique.","g":"4 × 10","r":"bola alta e lenta","p":"bola com efeito e profunda","x":"momento do contato","i":"direção e profundidade"},{"c":"RT003","n":"Um passo para dentro","f":"RT","e":["A","C"],"o":"","m":"A cada bola da troca, a base avança cerca de 30 cm para dentro da quadra.","g":"3 séries de troca até 8 bolas","r":"avanço a cada duas bolas","p":"avanço obrigatório a cada bola","x":"ganho de terreno mantendo equilíbrio","i":"erros por falta de tempo nas primeiras sessões"},{"c":"RT004","n":"Bola curta é convite","f":"RT","e":["A","C"],"o":"","m":"Bola curta do professor; entrar e finalizar à frente.","g":"4×8","r":"bola mais alta e central","p":"bola curta com efeito e ângulo","x":"decisão de entrar e ponto de contato","i":"o resultado da bola"},{"c":"RT005","n":"Duas alturas, mesmo alvo","f":"RT","e":["A","C"],"o":"","m":"Mesma direção com trajetória alta e depois direta; comparar o tempo de resposta do parceiro.","g":"2 × 10 de cada","r":"sem comparação, só executar","p":"o parceiro relata a diferença percebida","x":"compreensão do conceito","i":"consistência"},{"c":"RT006","n":"Meia quadra permanente","f":"RT","e":["A","C"],"o":"","m":"Trocar de dentro da linha de base durante toda a série.","g":"3 × 8 bolas","r":"sobre a linha","p":"um metro para dentro","x":"preparação encurtada compatível com o tempo","i":"número de erros"},{"c":"RT007","n":"Devolução que rouba tempo","f":"RT","e":["A","C"],"o":"","m":"Devolver na subida do quique, sem exceção.","g":"3 × 10","r":"apenas segundo saque","p":"primeiro saque","x":"posição de espera e primeiro passo","i":"profundidade"},{"c":"RT008","n":"Defesa acelerada","f":"RT","e":["C"],"o":"","m":"Na corrida, acelerar a cruzada em vez de levantar a bola.","g":"3×8","r":"bola menos aberta","p":"bola muito aberta com pressão","x":"estabilização e aceleração sob desequilíbrio","i":"taxa de acerto inicial"},{"c":"RT009","n":"As duas defesas","f":"RT","e":["A","C"],"o":"","m":"Alternar defesa alta e defesa acelerada, por chamada do professor durante o ponto.","g":"4 × 6 pontos","r":"alternância anunciada antes","p":"chamada durante o deslocamento","x":"capacidade de escolher a opção pedida","i":"qualidade fina de cada uma"},{"c":"RT010","n":"Variação como redução","f":"RT","e":["A","C"],"o":"","m":"Alternar ritmo, altura e efeito para tirar a referência de tempo do parceiro.","g":"3 × 10","r":"duas variáveis","p":"as quatro variáveis","x":"intenção de tirar referência, não de acertar mais","i":"consistência"},{"c":"RT011","n":"Split antecipado","f":"RT","e":["A","C"],"o":"","m":"Iniciar o salto lendo o corpo do parceiro, não a bola.","g":"3 × 12","r":"parceiro exagera o gesto","p":"parceiro disfarça","x":"olhar no corpo do outro após o próprio contato","i":"o golpe seguinte"},{"c":"RT012","n":"Corta o tempo na subida","f":"RT","e":["C"],"o":"","m":"Subir à rede em bola que normalmente não pediria subida.","g":"3×6","r":"bola claramente curta","p":"bola neutra","x":"posição alcançada antes do golpe adversário","i":"ponto ganho ou perdido"},{"c":"RT013","n":"Braço solto, bola rápida","f":"RT","e":["A","C"],"o":"","m":"Séries alternando esforço percebido (50%, 70%, máximo); comparar velocidade e regularidade.","g":"3 × 8 em cada nível","r":"dois níveis de esforço","p":"medir com radar ou cronometrar","x":"percepção de que solto produz mais que forçado","i":"direção"},{"c":"RT014","n":"Terreno ganho por ponto","f":"RT","e":["C"],"o":"","m":"Registrar quantos metros o jogador avançou ao longo do ponto.","g":"10 pontos com registro","r":"registro apenas do ponto final","p":"meta de avanço por ponto","x":"consciência de posição","i":"técnica"},{"c":"TR001","n":"Trilho de ganho de quadra","f":"TR","e":["A","C"],"o":"Avançar terreno metro a metro, com o adversário recuando a cada bola.","m":"Combinado: três bolas fundas cruzadas, e a cada uma o jogador avança meio metro. Marque com cones as três posições de avanço. O parceiro devolve sempre fundo e cruzado.","g":"3 séries de 9 bolas","r":"Duas bolas em vez de três; o parceiro alimenta de cesto em vez de trocar.","p":"O avanço é decidido pelo jogador conforme a bola do outro, sem cones.","x":"A profundidade da bola. É ela que compra o metro — não a velocidade.","i":"A qualidade técnica do golpe. O objeto é o terreno ganho, e ele se mede nos pés."},{"c":"TR002","n":"Trilho de negação de ângulo","f":"TR","e":["A","C"],"o":"Tirar do adversário a possibilidade de abrir a quadra.","m":"Combinado: o parceiro joga uma bola angulada; o jogador responde funda ao centro; o parceiro devolve sem ângulo; o jogador escolhe o lado. Quatro bolas, sempre iguais.","g":"3 séries de 8 pontos","r":"O parceiro angula sempre para o mesmo lado.","p":"O parceiro escolhe o lado do ângulo; o jogador reconhece e neutraliza.","x":"A altura sobre a rede na bola central. Sem altura, ela não chega funda.","i":"A ausência de brilho da jogada. A bola central é a mais subestimada e a mais eficaz."},{"c":"TR003","n":"Trilho da bola que autoriza","f":"TR","e":["A","C"],"o":"Reconhecer, antes de preparar, se a bola é de neutro, de ataque ou de defesa.","m":"Treinador alimenta três tipos de bola em ordem aleatória: funda e alta, curta e lenta, profunda e rápida. O jogador diz em voz alta 'neutra', 'ataque' ou 'defesa' antes de bater.","g":"4 séries de 10 bolas","r":"Duas categorias apenas: ataque e não-ataque.","p":"Sem falar em voz alta; a resposta aparece na escolha do golpe.","x":"A correspondência entre o que ele nomeou e o que ele jogou.","i":"O erro da bola. O objeto é o reconhecimento, e ele acontece antes do contato."},{"c":"TR004","n":"Trilho de virada da quadra","f":"TR","e":["A","C"],"o":"Contornar para o lado dominante a partir da bola que já veio ao meio.","m":"Combinado: duas bolas cruzadas do lado não dominante, terceira bola do parceiro para o meio, o jogador contorna e joga inside out. Sempre a mesma sequência.","g":"3 séries de 8 sequências","r":"O parceiro joga a terceira bola sempre no mesmo ponto do meio.","p":"O parceiro varia: às vezes a bola vem ao meio, às vezes fica no canto. O jogador decide.","x":"A posição dos pés que viabiliza o contorno — ela acontece antes da bola chegar.","i":"A velocidade do inside out. O objeto é a leitura da bola que permite virar."},{"c":"TR005","n":"Trilho de forçar a bola curta","f":"TR","e":["A","C"],"o":"Produzir a bola curta em vez de esperar por ela.","m":"Combinado: duas bolas fundas com altura, obrigando o parceiro a recuar; na terceira ele devolve obrigatoriamente curta; o jogador entra e ataca de meia quadra.","g":"3 séries de 8 sequências","r":"O parceiro entrega a bola curta sem as duas fundas anteriores.","p":"O parceiro decide quando encurtar; o jogador precisa reconhecer e entrar.","x":"A altura e a profundidade das duas primeiras bolas. São elas que produzem a terceira.","i":"O erro do ataque final. Se as duas primeiras bolas empurraram, o trilho funcionou."},{"c":"TR006","n":"Trilho de transição defesa-ataque","f":"TR","e":["A","C"],"o":"Sair da defesa devolvendo o ponto ao neutro, e atacar na bola seguinte.","m":"Combinado: treinador alimenta uma bola profunda que empurra o jogador para trás; ele responde alta e funda ao centro; o treinador alimenta uma bola média; o jogador ataca.","g":"3 séries de 8 sequências","r":"A bola defensiva é alimentada menos profunda.","p":"Duas bolas defensivas antes da neutralização.","x":"A bola do meio: ela é de neutralização, não de ataque. Atacar dela é o erro do trilho.","i":"A qualidade da bola defensiva. Sair viva já é o resultado dessa bola."},{"c":"TR007","n":"Trilho de mudança de direção","f":"TR","e":["A","C"],"o":"Mudar a diagonal apenas a partir de bola confortável.","m":"Treinador alimenta alternando bolas confortáveis (cintura, corpo equilibrado) e desconfortáveis (alta, larga, em corrida). O jogador só muda de direção nas confortáveis; nas outras, devolve na mesma diagonal.","g":"4 séries de 10 bolas","r":"As bolas confortáveis são anunciadas antes.","p":"Sem anúncio, com o jogador declarando em voz alta 'muda' ou 'mantém'.","x":"A decisão, não a execução. Mudar de bola difícil é erro mesmo quando a bola entra.","i":"O erro da bola mantida na diagonal. Ela está certa por definição."},{"c":"TR008","n":"Trilho de subida intencional","f":"TR","e":["A","C"],"o":"Subir à rede atrás da bola que foi feita para permitir a subida.","m":"Combinado: bola funda que empurra, bola de aproximação baixa no lado fraco do parceiro, subida, voleio de decisão. Quatro tempos, sempre iguais.","g":"3 séries de 8 sequências","r":"A bola de aproximação é alimentada pelo treinador; o jogador só sobe e voleia.","p":"O parceiro passa de verdade, e o ponto é disputado até o fim.","x":"A altura da bola de aproximação. Bola alta dá tempo, e tempo dá passada.","i":"A qualidade do voleio nas primeiras séries. O objeto é a escolha da bola de subida."},{"c":"TR009","n":"Semiaberto de ganho de quadra","f":"TR","e":["A","C"],"o":"Avançar terreno em ponto vivo, a partir de entrada controlada.","m":"Treinador alimenta uma bola neutra ao centro; a partir dela o ponto é livre. Vale ponto duplo para quem terminar o ponto tendo o pé dentro da quadra.","g":"3 séries de 8 pontos","r":"Alimentação mais alta e mais lenta.","p":"Alimentação profunda, obrigando a ganhar quadra a partir de posição pior.","x":"Se o avanço acontece por escolha ou por acaso.","i":"O resultado do ponto. A medida é o terreno, não o placar."},{"c":"TR010","n":"Semiaberto de defesa para ataque","f":"TR","e":["A","C"],"o":"Reconhecer, em ponto vivo, o momento em que a defesa acabou.","m":"Treinador alimenta uma bola que empurra o jogador para fora; o ponto segue vivo. O jogador precisa neutralizar antes de atacar.","g":"3 séries de 8 pontos","r":"A bola de entrada é menos agressiva.","p":"Duas bolas de pressão na entrada antes de o ponto ficar livre.","x":"A bola de transição — a que devolve o ponto ao neutro.","i":"Atacar cedo nas primeiras séries. O erro faz parte do reconhecimento."},{"c":"TR011","n":"Semiaberto de bola curta","f":"TR","e":["A","C"],"o":"Entrar e atacar a bola curta em ponto vivo.","m":"Treinador alimenta uma bola curta em momento não anunciado durante a troca; o ponto segue.","g":"3 séries de 10 pontos","r":"A bola curta é anunciada antes de sair.","p":"A curta vem sempre depois de duas bolas fundas que o jogador teve de produzir.","x":"A entrada em diagonal e o pé de apoio.","i":"O erro do ataque. Atacar e errar vale mais que esperar e devolver."},{"c":"TR012","n":"Semiaberto de saque e ganho de quadra","f":"TR","e":["A","C"],"o":"Encadear o saque com o avanço de terreno.","m":"Saque real, e o jogador precisa terminar o ponto com o pé dentro da quadra para valer ponto duplo. O ponto segue livre depois da devolução.","g":"3 séries de 8 pontos","r":"Saque à meia velocidade.","p":"Só vale ponto se terminar dentro da quadra.","x":"A entrada para dentro logo após o saque.","i":"O percentual de primeiro saque. O objeto é o terreno depois dele."},{"c":"TR013","n":"Semiaberto de negação de ângulo","f":"TR","e":["A","C"],"o":"Reconhecer, em ponto vivo, quando o adversário está em posição de angular.","m":"Treinador alimenta uma bola que coloca o parceiro dentro da quadra; o jogador precisa neutralizar pelo centro antes de retomar a iniciativa.","g":"3 séries de 8 pontos","r":"A bola de entrada coloca o parceiro menos à frente.","p":"O parceiro tem liberdade de angular sempre que quiser.","x":"A leitura da posição do outro, e não da bola.","i":"A beleza da jogada. Bola central e alta pontuando é o resultado desejado."},{"c":"TR014","n":"Semiaberto de mudança de direção","f":"TR","e":["A","C"],"o":"Escolher, em ponto vivo, a bola que permite mudar.","m":"Troca cruzada iniciada por alimentação; o jogador pode mudar de direção quando quiser, mas perde o ponto se mudar de bola em corrida.","g":"3 séries de 8 pontos","r":"A regra vale só para um dos jogadores.","p":"A regra vale para os dois, com o parceiro tentando forçar mudanças ruins.","x":"O critério da mudança, não o resultado dela.","i":"O erro da bola mudada de posição correta."},{"c":"TR015","n":"Semiaberto de subida","f":"TR","e":["A","C"],"o":"Decidir a subida em ponto vivo, sem aviso.","m":"Ponto iniciado por alimentação neutra; o jogador precisa subir em algum momento do ponto, mas escolhendo a bola.","g":"3 séries de 8 pontos","r":"A subida é anunciada antes do ponto.","p":"Vale ponto duplo se a subida acontecer antes da quinta bola.","x":"A bola escolhida para subir — foi ela quem empurrou o adversário?","i":"O resultado do voleio. O objeto é a escolha da bola de aproximação."},{"c":"TR016","n":"Semiaberto do perfil","f":"TR","e":["A","C"],"o":"Trabalhar a intenção principal do jogador dentro do ponto vivo.","m":"A entrada é a situação típica do perfil do jogador: bola profunda para quem joga de trás com peso, bola rápida e baixa para quem joga sobre a linha, alternada para o perfil completo.","g":"3 séries de 8 pontos","r":"Entrada mais fácil e mais previsível.","p":"Entrada na situação menos confortável do perfil, para trabalhar o buraco em vez da arma.","x":"Se o jogador está jogando o próprio jogo ou o jogo que imagina que devia jogar.","i":"A comparação com outro aluno. O perfil é dele."},{"c":"TR017","n":"Aberto: o pé dentro","f":"TR","e":["A","C"],"o":"Premiar o avanço de terreno no ponto disputado.","m":"Games normais. Ponto vale dobro se o jogador terminar com pelo menos um pé dentro da linha de base.","g":"2 a 4 games","r":"A regra vale só para quem está trabalhando o tema.","p":"Só vale ponto se terminar dentro da quadra.","x":"Se o avanço aparece sem lembrete.","i":"Tudo o mais durante o game. A regra faz o trabalho."},{"c":"TR018","n":"Aberto: proibido angular de trás","f":"TR","e":["A","C"],"o":"Instalar a ordem correta — ganhar quadra antes de angular.","m":"Games normais. Perde o ponto quem jogar bola angulada estando atrás da linha de base.","g":"2 a 4 games","r":"A regra é avisada, não penalizada, nas primeiras duas semanas.","p":"A regra vale para os dois jogadores.","x":"A consciência de posição antes da escolha do alvo.","i":"As bolas angulares de dentro da quadra. Essas são o objetivo."},{"c":"TR019","n":"Aberto: a intenção declarada","f":"TR","e":["A","C"],"o":"Instalar a intencionalidade de cada bola.","m":"Antes de cada ponto, o jogador declara em voz alta a intenção da primeira bola: empurrar, abrir, neutralizar ou terminar. O ponto é disputado normalmente.","g":"2 a 3 games","r":"Duas intenções possíveis apenas.","p":"Intenção declarada silenciosamente e verificada no debriefing.","x":"A correspondência entre o declarado e o jogado.","i":"O resultado do ponto. A medida é a fidelidade à intenção."},{"c":"TR020","n":"Aberto: quatro bolas","f":"TR","e":["A","C"],"o":"Encadear intenções sem alongar o ponto.","m":"Games normais. Ponto vale dobro se terminar em até quatro bolas com o ponto tendo sido construído — isto é, se as bolas anteriores tiveram função diferente entre si.","g":"2 a 4 games","r":"Contagem apenas, sem pontuação dobrada.","p":"O jogador precisa nomear as funções das bolas no fim de cada ponto.","x":"Se existe encadeamento ou se as bolas são todas iguais.","i":"Pontos longos. Eles acontecem e não são erro."},{"c":"TR021","n":"Aberto: sem bola de espera","f":"TR","e":["A","C"],"o":"Eliminar a bola sem intenção.","m":"Games normais. O jogador perde o ponto se jogar duas bolas seguidas sem mudar nada — mesma altura, mesma direção, mesma profundidade.","g":"2 a 3 games","r":"A regra vale a partir da terceira bola do ponto.","p":"A regra vale desde a primeira bola.","x":"A capacidade de dar função a toda bola, inclusive à de sustentação.","i":"Erros que aparecem por excesso de mudança nas primeiras séries."},{"c":"TR022","n":"Aberto: subida obrigatória","f":"TR","e":["A","C"],"o":"Instalar a rede como conclusão, não como estilo.","m":"Games normais. O jogador precisa subir à rede pelo menos uma vez por game, e escolher a bola.","g":"2 a 4 games","r":"A subida pode acontecer atrás de qualquer bola.","p":"A subida só vale se acontecer atrás de bola que fez o adversário recuar.","x":"A escolha da bola de subida.","i":"O resultado da subida. Subir atrás da bola certa e perder o ponto é execução correta."},{"c":"TR023","n":"Aberto: o piso do jogo","f":"TR","e":["A","C"],"o":"Adaptar a intenção ao piso e à velocidade da quadra.","m":"Games normais, com uma condição que simula o piso: bola mais murcha para simular saibro, quadra encurtada para simular piso rápido. O jogador ajusta a construção.","g":"2 a 4 games","r":"Uma condição por sessão.","p":"Alternância de condição a cada game, sem aviso.","x":"Se o jogador muda a construção conforme a condição ou insiste no mesmo jogo.","i":"A preferência dele por uma das condições. Ela é informação de perfil, não erro."},{"c":"TR024","n":"Aberto: dois perfis","f":"TR","e":["A","C"],"o":"Reconhecer o perfil do adversário e jogar contra ele.","m":"Games normais, com os dois jogadores sabendo o perfil um do outro. Cada um precisa nomear, no fim do game, uma jogada que usou por causa do perfil do outro.","g":"2 a 4 games","r":"O professor nomeia os perfis antes.","p":"Os jogadores identificam sozinhos o perfil do outro, sem saber de antemão.","x":"A leitura, não o resultado.","i":"O placar. É a leitura que se está treinando."},{"c":"PT001","n":"Leitura de Bola Cruzada e Troca de Direção","f":"PT","e":["A","C"],"o":"Ensina a diferença entre sustentar a cruzada e aproveitar a abertura pra mudar de direção.","m":"Treinador alimenta bolas cruzadas; o jogador aprende a reconhecer quando a bola permite trocar de direção (abrir pra paralela) e quando deve manter a cruzada.","g":"4 séries de 6 bolas","r":"Só bolas cruzadas, sem exigir a troca — foco em sustentar o padrão.","p":"Mistura bolas que permitem e que não permitem trocar, sem avisar qual é qual.","x":"Se o jogador espera a bola certa antes de trocar, em vez de trocar por impulso.","i":"O erro da bola trocada errado — é a primeira vez que ele está aprendendo a diferença."},{"c":"PT002","n":"Recuperação ao Centro Relativo","f":"PT","e":["A","C"],"o":"Introduz o conceito de centro relativo: a posição de recuperação depende do próprio golpe, não é um ponto fixo na quadra.","m":"Depois de cada golpe, o jogador recupera para o centro relativo ao próprio golpe (não o centro geométrico da quadra), evitando afundar demais ou abrir demais o ângulo de cobertura.","g":"Série de 10 bolas com deslocamento","r":"Treinador aponta verbalmente pra onde recuperar logo após cada bola.","p":"Jogador decide sozinho a posição de recuperação, sem aviso.","x":"Se a posição de recuperação cobre o próximo golpe provável do adversário, sem deixar faltar nem sobrar quadra.","i":"A velocidade da recuperação — primeiro a posição certa, depois a velocidade."},{"c":"PT003","n":"Pop, Push, Open, Close","f":"PT","e":["A","C"],"o":"Instala um padrão tático nomeado: arma profundo, empurra angulado, fecha na mudança de direção.","m":"Sequência de bolas: uma profunda que arma (pop), uma angulada cruzada que empurra o adversário pra fora (push/open), e a definição mudando de direção na paralela (close), fechando o ponto.","g":"4 séries de 4 bolas","r":"Sequência fracionada, bola por bola, com pausa pra confirmar a intenção de cada uma.","p":"Sequência em ritmo de ponto real, com adversário reagindo de verdade.","x":"A intenção de cada bola — armar, empurrar, fechar — não só acertar a bola.","i":"Errar a sequência fora de ordem no início — o padrão se instala repetindo."},{"c":"PT004","n":"Empurra e Muda de Direção","f":"PT","e":["A","C"],"o":"Jogada clássica de construção: empurrar pra trás abre a mudança de direção que fecha o ponto.","m":"Jogador empurra o adversário pra trás com uma bola alta e profunda na paralela (ou inside-out), recupera ao centro, recebe a bola que volta mais central e muda de direção pra fechar o ponto.","g":"4 séries de 4 bolas","r":"Bola de empurrar alimentada, só a mudança de direção decidida pelo jogador.","p":"Sequência completa em bola viva, incluindo a recuperação ao centro.","x":"A profundidade e altura da bola que empurra — ela precisa realmente tirar o adversário da posição.","i":"A velocidade da mudança de direção — primeiro empurrar bem, a mudança vem depois."},{"c":"PT005","n":"Abre e Sobe à Rede","f":"PT","e":["A","C"],"o":"Combina abertura de quadra com subida à rede num padrão de pressão só.","m":"Jogador abre a quadra na cruzada (FH ou BH), cortando o tempo do adversário, e usa essa vantagem para fazer um approach pra dentro da quadra, finalizando com um voleio no lado oposto.","g":"4 séries de 4 sequências","r":"Abertura alimentada, approach e voleio em bola parada.","p":"Sequência completa em bola viva, com adversário tentando cobrir o voleio.","x":"O corte de tempo na bola que abre — ela precisa chegar antes que o adversário se reorganize.","i":"O resultado do voleio isolado — o que importa é a sequência abertura-approach-voleio completa."},{"c":"PT006","n":"Gatilho de Subida à Rede","f":"PT","e":["A","C"],"o":"Transformar subida à rede de hábito raro em decisão automática sempre que a bola permitir.","m":"Rally de fundo em jogo aberto (não um padrão fixo). O jogador precisa reconhecer, em tempo real, o momento em que a bola do adversário vem curta, lenta ou sem profundidade — e só nesse momento decide subir à rede. Fora desse gatilho, segue a troca.","g":"6-8 pontos de rally livre por série, 3 séries","r":"Treinador avisa em voz alta cada vez que o gatilho aparece, até o jogador aprender a reconhecer sozinho.","p":"Sem aviso do treinador — o jogador decide por conta própria, inclusive sob pressão de placar.","x":"A decisão, não a execução do voleio — o erro mais comum é subir tarde demais, depois que a vantagem já passou.","i":"Contar quantas vezes o gatilho apareceu e quantas o jogador realmente subiu — a maioria dos jogadores sobe muito menos do que deveria, mesmo sabendo a teoria."},{"c":"PT007","n":"Golpe de Maior Expectativa","f":"PT","e":["A","C"],"o":"Decidir o golpe pela probabilidade real de ganhar o ponto, não pela vontade de resolver rápido.","m":"Pontos reais em que, antes de cada golpe de decisão, o jogador precisa escolher entre duas opções nomeadas pelo treinador: a de maior risco (ângulo fechado, pouca margem) e a de maior probabilidade (profundidade, margem maior). Depois do ponto, revisar junto qual escolha o aproximou mais de ganhar o jogo, não só o ponto isolado.","g":"1 set jogado com essa lente, revisão a cada troca de lado","r":"Treinador para o ponto depois do golpe de decisão e pergunta qual das duas opções o jogador escolheu, antes de dizer se foi ponto ou erro.","p":"Sem pausa — o jogador narra em voz alta, depois do ponto, qual risco assumiu e por quê.","x":"A lógica da escolha, não o resultado do ponto — um golpe de alto risco que funcionou uma vez não vira hábito só por isso.","i":"Jogador que confunde 'jogar seguro' com 'jogar sem intenção' — o objetivo não é sempre a opção mais segura, é a de maior retorno esperado dado o placar e a situação."},{"c":"PT008","n":"Profundidade Acima de Velocidade","f":"PT","e":["A","C"],"o":"Empurrar o adversário pra trás da linha de base como ferramenta tática, antes de buscar o golpe de potência.","m":"Troca de fundo em que o único critério de sucesso é a profundidade da bola (últimos 2 metros antes da linha de fundo) — velocidade e potência ficam de fora da avaliação. Cones ou fita marcam a zona de profundidade alvo.","g":"4 séries de 10 bolas cruzadas, alternando lado","r":"Bola com spin alto e ritmo controlado, só focando em passar a marca de profundidade.","p":"Mesma zona de profundidade, mas agora dentro de um rally de pontos reais, sob pressão de resultado.","x":"Quantas bolas da série caem na zona de profundidade — não a potência do golpe.","i":"Jogador que troca profundidade por velocidade no meio da série, assim que sente que está ganhando a troca — é exatamente o padrão que o drill quer corrigir."}];
const PORCODIGO = Object.fromEntries(DRILLS.map((d) => [d.c, d]));

/* Drills disponíveis para o nível do jogador: competidor usa o estágio C; os demais, A. */
function drillsDoNivel(nivel) {
  const estagio = nivel === "competidor" ? "C" : "A";
  return DRILLS.filter((d) => d.e.includes(estagio));
}

module.exports = { FAMILIAS, DRILLS, PORCODIGO, drillsDoNivel };
